'use client';

/**
 * Breakpoints Manager Component
 *
 * Manages hardware and software breakpoints for debugging
 */

import React, { useState, useCallback, useRef } from 'react';
import { GdbClient } from '../lib/gdb/GdbClient';

export interface Breakpoint {
  id: string;
  address: string;
  type: 'hardware' | 'software';
  enabled: boolean;
  condition?: string;
  hitCount?: number;
  symbol?: string;
  description?: string;
}

interface BreakpointsManagerProps {
  gdbClient: GdbClient | null;
  isConnected: boolean;
  onOutput?: (message: string) => void;
  breakpoints?: Breakpoint[];
  onBreakpointsChange?: (breakpoints: Breakpoint[]) => void;
}

export default function BreakpointsManager({
  gdbClient,
  isConnected,
  onOutput,
  breakpoints: externalBreakpoints,
  onBreakpointsChange
}: BreakpointsManagerProps) {
  const [breakpoints, setBreakpointsInternal] = useState<Breakpoint[]>(externalBreakpoints || []);

  // Wrapper to update both internal state and notify parent
  const setBreakpoints = (newBreakpoints: Breakpoint[] | ((prev: Breakpoint[]) => Breakpoint[])) => {
    if (typeof newBreakpoints === 'function') {
      setBreakpointsInternal(prev => {
        const updated = newBreakpoints(prev);
        onBreakpointsChange?.(updated);
        return updated;
      });
    } else {
      setBreakpointsInternal(newBreakpoints);
      onBreakpointsChange?.(newBreakpoints);
    }
  };

  // Sync with external breakpoints when they change
  React.useEffect(() => {
    if (externalBreakpoints) {
      setBreakpointsInternal(externalBreakpoints);
    }
  }, [externalBreakpoints]);
  const [newAddress, setNewAddress] = useState('');
  const [newSymbol, setNewSymbol] = useState('');
  const [newCondition, setNewCondition] = useState('');
  const [breakpointType, setBreakpointType] = useState<'hardware' | 'software'>('software');
  const [showAddForm, setShowAddForm] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Generate unique ID for breakpoints
  const generateId = () => `bp_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

  // Add a new breakpoint
  const handleAddBreakpoint = useCallback(async () => {
    if (!gdbClient || !isConnected) {
      onOutput?.('[Error] Not connected to target');
      return;
    }

    const addressOrSymbol = newAddress || newSymbol;
    if (!addressOrSymbol) {
      onOutput?.('[Error] Address or symbol required');
      return;
    }

    try {
      // Insert breakpoint via GDB
      await gdbClient.insertBreakpoint(addressOrSymbol, breakpointType === 'hardware');

      // Add to local state
      const newBreakpoint: Breakpoint = {
        id: generateId(),
        address: addressOrSymbol,
        type: breakpointType,
        enabled: true,
        condition: newCondition || undefined,
        symbol: newSymbol || undefined,
        description: newSymbol ? `Symbol: ${newSymbol}` : `Address: ${addressOrSymbol}`,
        hitCount: 0
      };

      setBreakpoints(prev => [...prev, newBreakpoint]);
      onOutput?.(`[Breakpoint] Added ${breakpointType} breakpoint at ${addressOrSymbol}`);

      // Clear form
      setNewAddress('');
      setNewSymbol('');
      setNewCondition('');
      setShowAddForm(false);
    } catch (error) {
      onOutput?.(`[Error] Failed to add breakpoint: ${error}`);
    }
  }, [gdbClient, isConnected, newAddress, newSymbol, newCondition, breakpointType, onOutput, setBreakpoints]);

  // Remove a breakpoint
  const handleRemoveBreakpoint = useCallback(async (bp: Breakpoint) => {
    if (!gdbClient || !isConnected) {
      onOutput?.('[Error] Not connected to target');
      return;
    }

    try {
      // Remove from GDB
      await gdbClient.removeBreakpoint(bp.address, bp.type === 'hardware');

      // Remove from local state
      setBreakpoints(prev => prev.filter(b => b.id !== bp.id));
      onOutput?.(`[Breakpoint] Removed breakpoint at ${bp.address}`);
    } catch (error) {
      onOutput?.(`[Error] Failed to remove breakpoint: ${error}`);
    }
  }, [gdbClient, isConnected, onOutput, setBreakpoints]);

  // Toggle breakpoint enabled/disabled
  const handleToggleBreakpoint = useCallback(async (bp: Breakpoint) => {
    if (!gdbClient || !isConnected) {
      onOutput?.('[Error] Not connected to target');
      return;
    }

    try {
      if (bp.enabled) {
        // Disable by removing from GDB but keep in list
        await gdbClient.removeBreakpoint(bp.address, bp.type === 'hardware');
      } else {
        // Re-enable by adding back to GDB
        await gdbClient.insertBreakpoint(bp.address, bp.type === 'hardware');
      }

      // Update local state
      setBreakpoints(prev => prev.map(b =>
        b.id === bp.id ? { ...b, enabled: !b.enabled } : b
      ));

      onOutput?.(`[Breakpoint] ${bp.enabled ? 'Disabled' : 'Enabled'} breakpoint at ${bp.address}`);
    } catch (error) {
      onOutput?.(`[Error] Failed to toggle breakpoint: ${error}`);
    }
  }, [gdbClient, isConnected, onOutput, setBreakpoints]);

  // Clear all breakpoints
  const handleClearAll = useCallback(async () => {
    if (!gdbClient || !isConnected) {
      onOutput?.('[Error] Not connected to target');
      return;
    }

    try {
      // Remove all breakpoints from GDB
      for (const bp of breakpoints) {
        if (bp.enabled) {
          await gdbClient.removeBreakpoint(bp.address, bp.type === 'hardware');
        }
      }

      setBreakpoints([]);
      onOutput?.('[Breakpoint] Cleared all breakpoints');
    } catch (error) {
      onOutput?.(`[Error] Failed to clear breakpoints: ${error}`);
    }
  }, [gdbClient, isConnected, breakpoints, onOutput]);

  // Export breakpoints to JSON
  const handleExport = useCallback(() => {
    const data = JSON.stringify(breakpoints, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `breakpoints_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    onOutput?.('[Breakpoint] Exported breakpoints to file');
  }, [breakpoints, onOutput]);

  // Import breakpoints from JSON
  const handleImport = useCallback(async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    try {
      const text = await file.text();
      const imported = JSON.parse(text) as Breakpoint[];

      if (!Array.isArray(imported)) {
        throw new Error('Invalid breakpoint file format');
      }

      // Add imported breakpoints to GDB if connected
      if (gdbClient && isConnected) {
        for (const bp of imported) {
          if (bp.enabled) {
            try {
              await gdbClient.insertBreakpoint(bp.address, bp.type === 'hardware');
            } catch (error) {
              onOutput?.(`[Warning] Failed to set breakpoint at ${bp.address}: ${error}`);
              bp.enabled = false;
            }
          }
        }
      }

      setBreakpoints(imported);
      onOutput?.(`[Breakpoint] Imported ${imported.length} breakpoints`);
    } catch (error) {
      onOutput?.(`[Error] Failed to import breakpoints: ${error}`);
    }

    // Clear file input
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  }, [gdbClient, isConnected, onOutput, setBreakpoints]);

  return (
    <div className="h-full flex flex-col bg-gray-950 text-white">
      {/* Header */}
      <div className="flex items-center justify-between p-3 border-b border-gray-700">
        <h2 className="text-sm font-bold text-green-400">BREAKPOINTS</h2>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowAddForm(!showAddForm)}
            disabled={!isConnected}
            className="px-2 py-1 text-xs bg-green-600 hover:bg-green-500 disabled:bg-gray-600 rounded transition-colors"
          >
            + Add
          </button>
          <button
            onClick={handleClearAll}
            disabled={!isConnected || breakpoints.length === 0}
            className="px-2 py-1 text-xs bg-red-600 hover:bg-red-500 disabled:bg-gray-600 rounded transition-colors"
          >
            Clear All
          </button>
          <button
            onClick={handleExport}
            disabled={breakpoints.length === 0}
            className="px-2 py-1 text-xs bg-blue-600 hover:bg-blue-500 disabled:bg-gray-600 rounded transition-colors"
          >
            Export
          </button>
          <label className="px-2 py-1 text-xs bg-blue-600 hover:bg-blue-500 rounded cursor-pointer transition-colors">
            Import
            <input
              ref={fileInputRef}
              type="file"
              accept=".json"
              onChange={handleImport}
              className="hidden"
            />
          </label>
        </div>
      </div>

      {/* Add Breakpoint Form */}
      {showAddForm && (
        <div className="p-3 border-b border-gray-700 bg-gray-900">
          <div className="space-y-2">
            <div className="flex gap-2">
              <input
                type="text"
                placeholder="Address (e.g., 0x08000000)"
                value={newAddress}
                onChange={(e) => setNewAddress(e.target.value)}
                disabled={!!newSymbol}
                className="flex-1 px-2 py-1 bg-gray-800 border border-gray-600 rounded text-xs font-mono disabled:opacity-50"
              />
              <span className="text-xs text-gray-400 self-center">OR</span>
              <input
                type="text"
                placeholder="Symbol (e.g., main)"
                value={newSymbol}
                onChange={(e) => setNewSymbol(e.target.value)}
                disabled={!!newAddress}
                className="flex-1 px-2 py-1 bg-gray-800 border border-gray-600 rounded text-xs font-mono disabled:opacity-50"
              />
            </div>

            <div className="flex gap-2">
              <input
                type="text"
                placeholder="Condition (optional)"
                value={newCondition}
                onChange={(e) => setNewCondition(e.target.value)}
                className="flex-1 px-2 py-1 bg-gray-800 border border-gray-600 rounded text-xs font-mono"
              />
              <select
                value={breakpointType}
                onChange={(e) => setBreakpointType(e.target.value as 'hardware' | 'software')}
                className="px-2 py-1 bg-gray-800 border border-gray-600 rounded text-xs"
              >
                <option value="software">Software</option>
                <option value="hardware">Hardware</option>
              </select>
              <button
                onClick={handleAddBreakpoint}
                className="px-3 py-1 bg-green-600 hover:bg-green-500 rounded text-xs"
              >
                Add
              </button>
              <button
                onClick={() => {
                  setShowAddForm(false);
                  setNewAddress('');
                  setNewSymbol('');
                  setNewCondition('');
                }}
                className="px-3 py-1 bg-gray-600 hover:bg-gray-500 rounded text-xs"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Breakpoints List */}
      <div className="flex-1 overflow-auto p-3">
        {!isConnected ? (
          <div className="text-center text-gray-400 text-sm mt-8">
            Connect to target to manage breakpoints
          </div>
        ) : breakpoints.length === 0 ? (
          <div className="text-center text-gray-400 text-sm mt-8">
            No breakpoints set
          </div>
        ) : (
          <div className="space-y-2">
            {breakpoints.map((bp) => (
              <div
                key={bp.id}
                className={`p-3 rounded border ${
                  bp.enabled
                    ? 'bg-gray-900 border-gray-700'
                    : 'bg-gray-900/50 border-gray-800 opacity-60'
                }`}
              >
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <span className={`inline-block w-2 h-2 rounded-full ${
                        bp.enabled ? 'bg-red-500' : 'bg-gray-600'
                      }`} />
                      <span className="font-mono text-sm text-green-400">
                        {bp.address}
                      </span>
                      <span className={`text-xs px-2 py-0.5 rounded ${
                        bp.type === 'hardware'
                          ? 'bg-purple-600/30 text-purple-300'
                          : 'bg-blue-600/30 text-blue-300'
                      }`}>
                        {bp.type}
                      </span>
                    </div>

                    {bp.description && (
                      <div className="text-xs text-gray-400 ml-4">
                        {bp.description}
                      </div>
                    )}

                    {bp.condition && (
                      <div className="text-xs text-yellow-400 ml-4 mt-1">
                        Condition: {bp.condition}
                      </div>
                    )}

                    {bp.hitCount !== undefined && bp.hitCount > 0 && (
                      <div className="text-xs text-gray-500 ml-4 mt-1">
                        Hit count: {bp.hitCount}
                      </div>
                    )}
                  </div>

                  <div className="flex items-center gap-1 ml-2">
                    <button
                      onClick={() => handleToggleBreakpoint(bp)}
                      className="p-1 hover:bg-gray-700 rounded transition-colors"
                      title={bp.enabled ? 'Disable' : 'Enable'}
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        {bp.enabled ? (
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 9v6m4-6v6m7-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        ) : (
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
                        )}
                      </svg>
                    </button>
                    <button
                      onClick={() => handleRemoveBreakpoint(bp)}
                      className="p-1 hover:bg-gray-700 rounded transition-colors text-red-400"
                      title="Remove"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Status Bar */}
      <div className="px-3 py-2 border-t border-gray-700 bg-gray-900">
        <div className="flex items-center justify-between text-xs text-gray-400">
          <span>
            {breakpoints.length} breakpoint{breakpoints.length !== 1 ? 's' : ''}
            ({breakpoints.filter(bp => bp.enabled).length} enabled)
          </span>
          <span>
            HW: {breakpoints.filter(bp => bp.type === 'hardware').length} |
            SW: {breakpoints.filter(bp => bp.type === 'software').length}
          </span>
        </div>
      </div>
    </div>
  );
}

/**
 * Firmware Extractor Component
 *
 * Advanced firmware extraction tool for Black Magic Probe debugger.
 * Supports full flash dumps, region-specific extraction, multiple export formats,
 * and automatic chip detection with memory layout discovery.
 *
 * Architecture:
 * - FirmwareExtractor: Main component handling UI and orchestration
 * - ExtractionEngine: Core extraction logic (testable, hardware-independent)
 * - MemoryLayoutDetector: Automatic chip and memory detection
 * - FormatExporter: Handles different export formats (bin, hex, elf metadata)
 */

'use client';

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { GdbClient } from '../lib/gdb/GdbClient';
import { TargetInfo, MemoryRegion, ChipInfo } from '../lib/gdb/TargetInfo';
import { FileParser } from '../lib/flash/FileParser';
import { getCpuDefinitionManager } from '../lib/cpu/CpuDefinitionManager';

/**
 * Extraction configuration
 */
interface ExtractionConfig {
  startAddress: number;
  endAddress: number;
  chunkSize: number;
  verifyAfterRead: boolean;
  exportFormat: 'bin' | 'hex' | 'srec' | 'all';
  autoDetectSize: boolean;
}

/**
 * Extraction progress state
 */
interface ExtractionProgress {
  isExtracting: boolean;
  bytesRead: number;
  totalBytes: number;
  currentAddress: number;
  percentComplete: number;
  estimatedTimeRemaining: number;
  errors: string[];
}

/**
 * Memory region preset for common MCUs
 */
interface MemoryPreset {
  name: string;
  family: string;
  flash: { start: number; size: number };
  ram?: { start: number; size: number };
  eeprom?: { start: number; size: number };
}

/**
 * Common MCU memory presets
 */
const MEMORY_PRESETS: MemoryPreset[] = [
  {
    name: 'STM32F103C8T6 (BluePill)',
    family: 'STM32F1',
    flash: { start: 0x08000000, size: 0x10000 }, // 64KB
    ram: { start: 0x20000000, size: 0x5000 }     // 20KB
  },
  {
    name: 'STM32F103RCT6',
    family: 'STM32F1',
    flash: { start: 0x08000000, size: 0x40000 }, // 256KB
    ram: { start: 0x20000000, size: 0xC000 }     // 48KB
  },
  {
    name: 'STM32F407VG (Discovery)',
    family: 'STM32F4',
    flash: { start: 0x08000000, size: 0x100000 }, // 1MB
    ram: { start: 0x20000000, size: 0x20000 }     // 128KB
  },
  {
    name: 'STM32F429ZI',
    family: 'STM32F4',
    flash: { start: 0x08000000, size: 0x200000 }, // 2MB
    ram: { start: 0x20000000, size: 0x30000 }     // 192KB
  },
  {
    name: 'STM32F746NG (Discovery)',
    family: 'STM32F7',
    flash: { start: 0x08000000, size: 0x100000 }, // 1MB
    ram: { start: 0x20000000, size: 0x50000 }     // 320KB
  },
  {
    name: 'STM32H743ZI (Nucleo)',
    family: 'STM32H7',
    flash: { start: 0x08000000, size: 0x200000 }, // 2MB
    ram: { start: 0x20000000, size: 0x20000 }     // 128KB DTCM
  },
  {
    name: 'STM32L476RG (Nucleo)',
    family: 'STM32L4',
    flash: { start: 0x08000000, size: 0x100000 }, // 1MB
    ram: { start: 0x20000000, size: 0x18000 }     // 96KB
  },
  {
    name: 'STM32G474RE (Nucleo)',
    family: 'STM32G4',
    flash: { start: 0x08000000, size: 0x80000 },  // 512KB
    ram: { start: 0x20000000, size: 0x20000 }     // 128KB
  },
  {
    name: 'nRF52840',
    family: 'nRF52',
    flash: { start: 0x00000000, size: 0x100000 }, // 1MB
    ram: { start: 0x20000000, size: 0x40000 }     // 256KB
  },
  {
    name: 'nRF52832',
    family: 'nRF52',
    flash: { start: 0x00000000, size: 0x80000 },  // 512KB
    ram: { start: 0x20000000, size: 0x10000 }     // 64KB
  },
  {
    name: 'RP2040',
    family: 'RP2040',
    flash: { start: 0x10000000, size: 0x200000 }, // 2MB external
    ram: { start: 0x20000000, size: 0x42000 }     // 264KB
  },
  {
    name: 'SAMD21G18 (Arduino Zero)',
    family: 'SAMD',
    flash: { start: 0x00000000, size: 0x40000 },  // 256KB
    ram: { start: 0x20000000, size: 0x8000 }      // 32KB
  },
  {
    name: 'ESP32-C3',
    family: 'ESP32',
    flash: { start: 0x00000000, size: 0x400000 }, // 4MB external
    ram: { start: 0x3FC80000, size: 0x60000 }     // 384KB
  }
];

/**
 * Format exporter utility class
 */
class FormatExporter {
  /**
   * Export data as raw binary
   */
  static exportBinary(data: Uint8Array, filename: string): void {
    const blob = new Blob([data], { type: 'application/octet-stream' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
  }

  /**
   * Export data as Intel HEX format
   */
  static exportIntelHex(data: Uint8Array, baseAddress: number, filename: string): void {
    const hexString = FileParser.toIntelHex(data, baseAddress);
    const blob = new Blob([hexString], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
  }

  /**
   * Export data as Motorola S-record format
   */
  static exportSRecord(data: Uint8Array, baseAddress: number, filename: string): void {
    const srecString = FileParser.toSRecord(data, baseAddress);
    const blob = new Blob([srecString], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
  }

  /**
   * Generate metadata file with extraction information
   */
  static exportMetadata(
    config: ExtractionConfig,
    chipInfo: ChipInfo | null,
    extractedData: Uint8Array,
    filename: string
  ): void {
    const metadata = {
      timestamp: new Date().toISOString(),
      chip: chipInfo,
      extraction: {
        startAddress: `0x${config.startAddress.toString(16).toUpperCase()}`,
        endAddress: `0x${config.endAddress.toString(16).toUpperCase()}`,
        size: extractedData.length,
        checksum: FileParser.calculateChecksum(extractedData),
        format: config.exportFormat
      },
      tool: 'BattleMagic Firmware Extractor',
      version: '1.0.0'
    };

    const blob = new Blob([JSON.stringify(metadata, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
  }
}

/**
 * Main Firmware Extractor Component
 */
interface FirmwareExtractorProps {
  gdbClient: GdbClient | null;
  isConnected: boolean;
  selectedCpu?: string; // CPU definition ID for auto-configuration
}

export default function FirmwareExtractor({ gdbClient, isConnected, selectedCpu }: FirmwareExtractorProps) {
  // Debug logging on mount and prop changes
  useEffect(() => {
    console.log('[FirmwareExtractor] Component mounted/updated:', {
      isConnected,
      selectedCpu,
      hasGdbClient: !!gdbClient
    });
  }, [isConnected, selectedCpu, gdbClient]);

  // State management
  const [config, setConfig] = useState<ExtractionConfig>({
    startAddress: 0x08000000,
    endAddress: 0x08010000,
    chunkSize: 1024,
    verifyAfterRead: false, // Disabled by default - doubles extraction time and can cause timeouts
    exportFormat: 'all',
    autoDetectSize: true
  });

  const [progress, setProgress] = useState<ExtractionProgress>({
    isExtracting: false,
    bytesRead: 0,
    totalBytes: 0,
    currentAddress: 0,
    percentComplete: 0,
    estimatedTimeRemaining: 0,
    errors: []
  });

  const [detectedChip, setDetectedChip] = useState<ChipInfo | null>(null);
  const [memoryRegions, setMemoryRegions] = useState<MemoryRegion[]>([]);
  const [selectedPreset, setSelectedPreset] = useState<string>('');
  const [extractedData, setExtractedData] = useState<Uint8Array | null>(null);
  const [customStartAddress, setCustomStartAddress] = useState('0x08000000');
  const [customEndAddress, setCustomEndAddress] = useState('0x08010000');
  const [autoConfiguredCpu, setAutoConfiguredCpu] = useState<string | null>(null);

  // Refs for extraction control
  const abortControllerRef = useRef<AbortController | null>(null);
  const startTimeRef = useRef<number>(0);

  /**
   * Detect target chip and memory layout
   */
  const detectChipAndMemory = useCallback(async () => {
    if (!gdbClient || !isConnected) return;

    try {
      const targetInfo = new TargetInfo(gdbClient);
      const info = await targetInfo.getTargetInfo(true);

      if (info.chip) {
        setDetectedChip(info.chip);

        // Set memory regions
        const allRegions = [
          ...info.memory.flash,
          ...info.memory.ram,
          ...info.memory.other
        ];
        setMemoryRegions(allRegions);

        // Auto-configure flash region if detected
        if (info.memory.flash.length > 0) {
          const flashRegion = info.memory.flash[0];
          setConfig(prev => ({
            ...prev,
            startAddress: flashRegion.start,
            endAddress: flashRegion.start + flashRegion.size
          }));
          setCustomStartAddress(`0x${flashRegion.start.toString(16).toUpperCase()}`);
          setCustomEndAddress(`0x${(flashRegion.start + flashRegion.size).toString(16).toUpperCase()}`);
        }
      }
    } catch (error) {
      console.error('Failed to detect chip:', error);
      setProgress(prev => ({
        ...prev,
        errors: [...prev.errors, `Chip detection failed: ${error}`]
      }));
    }
  }, [gdbClient, isConnected]);

  /**
   * Auto-configure from CPU definition
   */
  useEffect(() => {
    if (selectedCpu && isConnected) {
      console.log('[FirmwareExtractor] Auto-config triggered with CPU:', selectedCpu);
      const cpuManager = getCpuDefinitionManager();
      const cpuDef = cpuManager.getDefinition(selectedCpu);

      if (cpuDef) {
        // Find flash region
        const flashRegion = cpuDef.memoryRegions.find(r => r.type === 'flash');
        if (flashRegion) {
          console.log('[FirmwareExtractor] Auto-configured from CPU:', cpuDef.name, 'Flash:', `0x${flashRegion.start.toString(16)} - 0x${flashRegion.end.toString(16)}`);
          setAutoConfiguredCpu(cpuDef.name); // Track which CPU was auto-configured
          setConfig(prev => ({
            ...prev,
            startAddress: flashRegion.start,
            endAddress: flashRegion.end
          }));
          setCustomStartAddress(`0x${flashRegion.start.toString(16).toUpperCase()}`);
          setCustomEndAddress(`0x${flashRegion.end.toString(16).toUpperCase()}`);
          setSelectedPreset(''); // Clear preset selection
        } else {
          console.warn('[FirmwareExtractor] No flash region found in CPU definition:', cpuDef.name);
        }
      } else {
        console.warn('[FirmwareExtractor] CPU definition not found:', selectedCpu);
      }
    }
  }, [selectedCpu, isConnected]);

  /**
   * Apply memory preset
   */
  const applyPreset = useCallback((presetName: string) => {
    const preset = MEMORY_PRESETS.find(p => p.name === presetName);
    if (!preset) return;

    setSelectedPreset(presetName);
    setConfig(prev => ({
      ...prev,
      startAddress: preset.flash.start,
      endAddress: preset.flash.start + preset.flash.size
    }));
    setCustomStartAddress(`0x${preset.flash.start.toString(16).toUpperCase()}`);
    setCustomEndAddress(`0x${(preset.flash.start + preset.flash.size).toString(16).toUpperCase()}`);
  }, []);

  /**
   * Export extracted firmware
   */
  const exportFirmware = useCallback((data?: Uint8Array) => {
    const exportData = data || extractedData;
    if (!exportData) return;

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const chipName = detectedChip?.description.replace(/[^a-zA-Z0-9]/g, '_') || 'unknown';
    const baseFilename = `firmware_${chipName}_${timestamp}`;

    // Export based on format selection
    if (config.exportFormat === 'bin' || config.exportFormat === 'all') {
      FormatExporter.exportBinary(exportData, `${baseFilename}.bin`);
    }

    if (config.exportFormat === 'hex' || config.exportFormat === 'all') {
      FormatExporter.exportIntelHex(exportData, config.startAddress, `${baseFilename}.hex`);
    }

    if (config.exportFormat === 'srec' || config.exportFormat === 'all') {
      FormatExporter.exportSRecord(exportData, config.startAddress, `${baseFilename}.srec`);
    }

    // Always export metadata
    FormatExporter.exportMetadata(config, detectedChip, exportData, `${baseFilename}_info.json`);
  }, [extractedData, config, detectedChip]);

  /**
   * Start firmware extraction
   */
  const startExtraction = useCallback(async () => {
    if (!gdbClient) {
      console.error('[FirmwareExtractor] No GDB client available');
      return;
    }

    if (!isConnected) {
      console.error('[FirmwareExtractor] Not attached to target');
      setProgress(prev => ({
        ...prev,
        errors: [...prev.errors, 'Error: Not attached to target. Please scan and attach to a target first.']
      }));
      return;
    }

    if (progress.isExtracting) {
      console.warn('[FirmwareExtractor] Extraction already in progress');
      return;
    }

    // Reset state
    setExtractedData(null);
    setProgress({
      isExtracting: true,
      bytesRead: 0,
      totalBytes: config.endAddress - config.startAddress,
      currentAddress: config.startAddress,
      percentComplete: 0,
      estimatedTimeRemaining: 0,
      errors: []
    });

    // Create abort controller for cancellation
    abortControllerRef.current = new AbortController();
    startTimeRef.current = Date.now();

    try {
      // Halt the target before reading flash memory
      console.log('[FirmwareExtractor] Attempting to halt target...');
      try {
        await gdbClient.halt();
        console.log('[FirmwareExtractor] Target halted successfully');

        // Verify target is halted by checking if we can read registers
        try {
          const pc = await gdbClient.readRegister('pc');
          console.log('[FirmwareExtractor] Target halted at PC:', `0x${pc?.toString(16)}`);
        } catch (regError) {
          console.warn('[FirmwareExtractor] Could not verify halt state:', regError);
        }
      } catch (haltError) {
        console.error('[FirmwareExtractor] Failed to halt target:', haltError);
        throw new Error('Failed to halt target. Cannot extract firmware while target is running.');
      }

      const totalBytes = config.endAddress - config.startAddress;
      const data = new Uint8Array(totalBytes);
      let bytesRead = 0;

      console.log('[FirmwareExtractor] Starting extraction:', {
        startAddress: `0x${config.startAddress.toString(16)}`,
        endAddress: `0x${config.endAddress.toString(16)}`,
        totalBytes,
        chunkSize: config.chunkSize
      });

      // Test read to verify memory is accessible
      console.log('[FirmwareExtractor] Performing test read...');
      try {
        const testChunk = await gdbClient.readMemory(config.startAddress, 16);
        console.log('[FirmwareExtractor] Test read successful, first bytes:', Array.from(testChunk.slice(0, 16)).map(b => b.toString(16).padStart(2, '0')).join(' '));

        // Check if all bytes are 0xFF (erased flash) or 0x00
        const allFF = testChunk.every(b => b === 0xFF);
        const all00 = testChunk.every(b => b === 0x00);

        if (allFF) {
          console.warn('[FirmwareExtractor] WARNING: Test read returned all 0xFF - flash may be erased or readout protection may be enabled');
          setProgress(prev => ({
            ...prev,
            errors: [...prev.errors, 'Warning: Memory appears erased (all 0xFF) - flash may be blank or protected']
          }));
        } else if (all00) {
          console.warn('[FirmwareExtractor] WARNING: Test read returned all 0x00 - memory may be inaccessible');
          setProgress(prev => ({
            ...prev,
            errors: [...prev.errors, 'Warning: Memory appears inaccessible (all 0x00)']
          }));
        }
      } catch (testError) {
        console.error('[FirmwareExtractor] Test read failed:', testError);

        // Check if this chip has protection registers defined
        const errorMsg = testError instanceof Error ? testError.message : String(testError);
        if (errorMsg.includes('E02') || errorMsg.includes('Failed to read memory')) {
          // Check protection registers from CPU definition
          if (selectedCpu) {
            const cpuManager = getCpuDefinitionManager();
            const cpuDef = cpuManager.getDefinition(selectedCpu);

            if (cpuDef?.protectionRegisters && cpuDef.protectionRegisters.length > 0) {
              console.log('[FirmwareExtractor] Checking protection registers...');

              for (const protReg of cpuDef.protectionRegisters) {
                try {
                  const regData = await gdbClient.readMemory(protReg.address, protReg.size);
                  const regValue = protReg.size === 4
                    ? new DataView(regData.buffer).getUint32(0, true)
                    : regData[0];

                  console.log(`[FirmwareExtractor] ${protReg.name} = 0x${regValue.toString(16)}`);

                  // Check if value indicates protection is enabled
                  if (protReg.protectedValues && protReg.protectedValues.includes(regValue)) {
                    const interpretation = protReg.interpretation?.[`0x${regValue.toString(16).toUpperCase().padStart(8, '0')}`];
                    let errorMessage = `${protReg.name} is ENABLED: ${interpretation || protReg.description}`;

                    if (protReg.disableCommand) {
                      errorMessage += `\n\nTo disable: ${protReg.disableCommand}`;
                    }
                    if (protReg.disableWarning) {
                      errorMessage += `\n\n⚠️ WARNING: ${protReg.disableWarning}`;
                    }

                    throw new Error(errorMessage);
                  }
                } catch (regError) {
                  console.warn(`[FirmwareExtractor] Could not read ${protReg.name}:`, regError);
                }
              }
            }
          }
        }

        throw new Error(`Memory read test failed at 0x${config.startAddress.toString(16)}: ${testError}. Memory may be protected or inaccessible.`);
      }

      // Extract in chunks
      while (bytesRead < totalBytes) {
        // Check for abort
        if (abortControllerRef.current?.signal.aborted) {
          throw new Error('Extraction aborted by user');
        }

        const currentAddress = config.startAddress + bytesRead;
        const remainingBytes = totalBytes - bytesRead;
        const chunkSize = Math.min(config.chunkSize, remainingBytes);

        // Read memory chunk
        try {
          const chunk = await gdbClient.readMemory(currentAddress, chunkSize);
          data.set(chunk, bytesRead);
          bytesRead += chunk.length;

          // Verify if enabled
          if (config.verifyAfterRead) {
            const verifyChunk = await gdbClient.readMemory(currentAddress, chunkSize);
            if (!arraysEqual(chunk, verifyChunk)) {
              throw new Error(`Verification failed at 0x${currentAddress.toString(16)}`);
            }
          }

          // Update progress
          const percentComplete = (bytesRead / totalBytes) * 100;
          const elapsedTime = Date.now() - startTimeRef.current;
          const bytesPerMs = bytesRead / elapsedTime;
          const remainingMs = remainingBytes / bytesPerMs;

          setProgress(prev => ({
            ...prev,
            bytesRead,
            currentAddress,
            percentComplete,
            estimatedTimeRemaining: Math.round(remainingMs / 1000)
          }));
        } catch (error) {
          console.error(`Failed to read at 0x${currentAddress.toString(16)}:`, error);
          setProgress(prev => ({
            ...prev,
            errors: [...prev.errors, `Read error at 0x${currentAddress.toString(16)}: ${error}`]
          }));

          // Try to continue with zeros for this chunk
          data.fill(0xFF, bytesRead, bytesRead + chunkSize);
          bytesRead += chunkSize;
        }

        // Small delay to prevent overwhelming the target
        await new Promise(resolve => setTimeout(resolve, 10));
      }

      // Extraction complete
      setExtractedData(data);
      setProgress(prev => ({
        ...prev,
        isExtracting: false,
        percentComplete: 100
      }));

      // Auto-export if data was successfully extracted
      if (data.length > 0) {
        exportFirmware(data);
      }
    } catch (error) {
      console.error('Extraction failed:', error);
      setProgress(prev => ({
        ...prev,
        isExtracting: false,
        errors: [...prev.errors, `Extraction failed: ${error}`]
      }));
    } finally {
      abortControllerRef.current = null;
    }
  }, [gdbClient, isConnected, config, progress.isExtracting, exportFirmware]);

  /**
   * Stop extraction
   */
  const stopExtraction = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
  }, []);

  /**
   * Helper: Compare two arrays
   */
  const arraysEqual = (a: Uint8Array, b: Uint8Array): boolean => {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (a[i] !== b[i]) return false;
    }
    return true;
  };

  /**
   * Parse address input
   */
  const parseAddress = (input: string): number => {
    const cleaned = input.trim().replace(/^0x/i, '');
    return parseInt(cleaned, 16);
  };

  /**
   * Auto-detect on connection - DISABLED: causes target to detach
   * Using CPU definition auto-config instead
   */
  // useEffect(() => {
  //   if (isConnected && config.autoDetectSize) {
  //     detectChipAndMemory();
  //   }
  // }, [isConnected, config.autoDetectSize, detectChipAndMemory]);

  return (
    <div className="flex flex-col h-full bg-gray-950 text-white p-4 overflow-y-auto">
      <div className="mb-4">
        <h2 className="text-xl font-bold text-green-400 mb-2">Firmware Extractor</h2>
        <p className="text-sm text-gray-400">
          Extract firmware from target MCU with automatic chip detection and multiple export formats
        </p>
      </div>

      {/* Connection Status */}
      <div className="mb-4 p-3 bg-gray-900 rounded border border-gray-700">
        <div className="flex items-center justify-between">
          <span className="text-sm">Target Status:</span>
          <span className={`text-sm font-mono ${isConnected ? 'text-green-400' : 'text-red-400'}`}>
            {isConnected ? 'Attached' : 'Not Attached'}
          </span>
        </div>
        {!isConnected && (
          <div className="mt-2 text-xs text-yellow-400 bg-yellow-900/20 border border-yellow-700/30 rounded p-2">
            ⚠️ Please scan for targets and attach to a target before extracting firmware
          </div>
        )}
        {detectedChip && (
          <div className="mt-2">
            <span className="text-sm text-gray-400">Detected Chip: </span>
            <span className="text-sm font-mono text-green-400">{detectedChip.description}</span>
            {detectedChip.family && (
              <span className="text-sm text-gray-500 ml-2">({detectedChip.family})</span>
            )}
          </div>
        )}
        {autoConfiguredCpu && (
          <div className="mt-2">
            <span className="text-sm text-gray-400">Auto-configured CPU: </span>
            <span className="text-sm font-mono text-blue-400">{autoConfiguredCpu}</span>
            <span className="text-xs text-gray-500 ml-2">(addresses set from CPU definition)</span>
          </div>
        )}
      </div>

      {/* Memory Configuration */}
      <div className="mb-4 p-3 bg-gray-900 rounded border border-gray-700">
        <h3 className="text-sm font-bold text-green-400 mb-2">Memory Configuration</h3>

        {/* Preset Selection */}
        <div className="mb-3">
          <label className="block text-xs text-gray-400 mb-1">Chip Preset:</label>
          <select
            value={selectedPreset}
            onChange={(e) => applyPreset(e.target.value)}
            className="w-full px-2 py-1 bg-gray-800 text-white text-sm rounded border border-gray-600 focus:border-green-400 focus:outline-none"
            disabled={!isConnected || progress.isExtracting}
          >
            <option value="">Custom</option>
            {MEMORY_PRESETS.map(preset => (
              <option key={preset.name} value={preset.name}>
                {preset.name}
              </option>
            ))}
          </select>
        </div>

        {/* Address Range */}
        <div className="grid grid-cols-2 gap-2 mb-3">
          <div>
            <label className="block text-xs text-gray-400 mb-1">Start Address:</label>
            <input
              type="text"
              value={customStartAddress}
              onChange={(e) => {
                setCustomStartAddress(e.target.value);
                try {
                  const addr = parseAddress(e.target.value);
                  setConfig(prev => ({ ...prev, startAddress: addr }));
                } catch {}
              }}
              className="w-full px-2 py-1 bg-gray-800 text-white text-sm font-mono rounded border border-gray-600 focus:border-green-400 focus:outline-none"
              placeholder="0x08000000"
              disabled={!isConnected || progress.isExtracting}
            />
          </div>
          <div>
            <label className="block text-xs text-gray-400 mb-1">End Address:</label>
            <input
              type="text"
              value={customEndAddress}
              onChange={(e) => {
                setCustomEndAddress(e.target.value);
                try {
                  const addr = parseAddress(e.target.value);
                  setConfig(prev => ({ ...prev, endAddress: addr }));
                } catch {}
              }}
              className="w-full px-2 py-1 bg-gray-800 text-white text-sm font-mono rounded border border-gray-600 focus:border-green-400 focus:outline-none"
              placeholder="0x08010000"
              disabled={!isConnected || progress.isExtracting}
            />
          </div>
        </div>

        {/* Size Display */}
        <div className="text-xs text-gray-400">
          Size: {((config.endAddress - config.startAddress) / 1024).toFixed(1)} KB
          ({(config.endAddress - config.startAddress).toLocaleString()} bytes)
        </div>
      </div>

      {/* Extraction Options */}
      <div className="mb-4 p-3 bg-gray-900 rounded border border-gray-700">
        <h3 className="text-sm font-bold text-green-400 mb-2">Extraction Options</h3>

        <div className="space-y-2">
          {/* Chunk Size */}
          <div className="flex items-center justify-between">
            <label className="text-xs text-gray-400">Chunk Size:</label>
            <select
              value={config.chunkSize}
              onChange={(e) => setConfig(prev => ({ ...prev, chunkSize: parseInt(e.target.value) }))}
              className="px-2 py-1 bg-gray-800 text-white text-sm rounded border border-gray-600 focus:border-green-400 focus:outline-none"
              disabled={!isConnected || progress.isExtracting}
            >
              <option value="256">256 bytes</option>
              <option value="512">512 bytes</option>
              <option value="1024">1024 bytes</option>
              <option value="2048">2048 bytes</option>
              <option value="4096">4096 bytes</option>
            </select>
          </div>

          {/* Export Format */}
          <div className="flex items-center justify-between">
            <label className="text-xs text-gray-400">Export Format:</label>
            <select
              value={config.exportFormat}
              onChange={(e) => setConfig(prev => ({ ...prev, exportFormat: e.target.value as 'bin' | 'hex' | 'srec' | 'all' }))}
              className="px-2 py-1 bg-gray-800 text-white text-sm rounded border border-gray-600 focus:border-green-400 focus:outline-none"
              disabled={!isConnected || progress.isExtracting}
            >
              <option value="bin">Binary (.bin)</option>
              <option value="hex">Intel HEX (.hex)</option>
              <option value="srec">S-Record (.srec)</option>
              <option value="all">All formats</option>
            </select>
          </div>

          {/* Verification */}
          <div className="flex items-center">
            <input
              type="checkbox"
              id="verify"
              checked={config.verifyAfterRead}
              onChange={(e) => setConfig(prev => ({ ...prev, verifyAfterRead: e.target.checked }))}
              className="mr-2"
              disabled={!isConnected || progress.isExtracting}
            />
            <label htmlFor="verify" className="text-xs text-gray-400">
              Verify after read (slower but safer)
            </label>
          </div>

          {/* Auto-detect */}
          <div className="flex items-center">
            <input
              type="checkbox"
              id="autodetect"
              checked={config.autoDetectSize}
              onChange={(e) => setConfig(prev => ({ ...prev, autoDetectSize: e.target.checked }))}
              className="mr-2"
              disabled={!isConnected || progress.isExtracting}
            />
            <label htmlFor="autodetect" className="text-xs text-gray-400">
              Auto-detect chip and memory size
            </label>
          </div>
        </div>
      </div>

      {/* Progress Display */}
      {progress.isExtracting && (
        <div className="mb-4 p-3 bg-gray-900 rounded border border-gray-700">
          <h3 className="text-sm font-bold text-green-400 mb-2">Extraction Progress</h3>

          {/* Progress Bar */}
          <div className="mb-2">
            <div className="w-full bg-gray-800 rounded-full h-4 relative overflow-hidden">
              <div
                className="bg-green-500 h-4 rounded-full transition-all duration-300"
                style={{ width: `${progress.percentComplete}%` }}
              />
              <span className="absolute inset-0 flex items-center justify-center text-xs font-mono">
                {progress.percentComplete.toFixed(1)}%
              </span>
            </div>
          </div>

          {/* Stats */}
          <div className="grid grid-cols-2 gap-2 text-xs">
            <div>
              <span className="text-gray-400">Current Address: </span>
              <span className="font-mono text-green-400">
                0x{progress.currentAddress.toString(16).toUpperCase().padStart(8, '0')}
              </span>
            </div>
            <div>
              <span className="text-gray-400">Bytes Read: </span>
              <span className="font-mono text-green-400">
                {progress.bytesRead.toLocaleString()} / {progress.totalBytes.toLocaleString()}
              </span>
            </div>
            {progress.estimatedTimeRemaining > 0 && (
              <div className="col-span-2">
                <span className="text-gray-400">Time Remaining: </span>
                <span className="font-mono text-green-400">
                  ~{progress.estimatedTimeRemaining}s
                </span>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Errors */}
      {progress.errors.length > 0 && (
        <div className="mb-4 p-3 bg-red-900/20 rounded border border-red-700">
          <h3 className="text-sm font-bold text-red-400 mb-2">Errors</h3>
          <div className="text-xs text-red-300 space-y-1 max-h-32 overflow-y-auto">
            {progress.errors.map((error, index) => (
              <div key={index} className="font-mono">{error}</div>
            ))}
          </div>
        </div>
      )}

      {/* Success Message */}
      {extractedData && !progress.isExtracting && (
        <div className="mb-4 p-3 bg-green-900/20 rounded border border-green-700">
          <h3 className="text-sm font-bold text-green-400 mb-2">Extraction Complete</h3>
          <div className="text-xs text-green-300">
            Successfully extracted {extractedData.length.toLocaleString()} bytes
            ({(extractedData.length / 1024).toFixed(1)} KB)
          </div>
          <div className="text-xs text-gray-400 mt-1">
            Checksum: 0x{FileParser.calculateChecksum(extractedData).toString(16).toUpperCase()}
          </div>
        </div>
      )}

      {/* Action Buttons */}
      <div className="flex gap-2 mt-auto">
        {!progress.isExtracting ? (
          <>
            <button
              onClick={startExtraction}
              disabled={!isConnected}
              className={`flex-1 px-4 py-2 text-sm font-bold rounded transition-colors ${
                isConnected
                  ? 'bg-green-600 hover:bg-green-500 text-white'
                  : 'bg-gray-700 text-gray-400 cursor-not-allowed'
              }`}
            >
              Start Extraction
            </button>
            {extractedData && (
              <button
                onClick={() => exportFirmware()}
                className="px-4 py-2 text-sm font-bold bg-blue-600 hover:bg-blue-500 text-white rounded transition-colors"
              >
                Re-export
              </button>
            )}
          </>
        ) : (
          <button
            onClick={stopExtraction}
            className="flex-1 px-4 py-2 text-sm font-bold bg-red-600 hover:bg-red-500 text-white rounded transition-colors"
          >
            Stop Extraction
          </button>
        )}
      </div>

      {/* Detected Memory Regions */}
      {memoryRegions.length > 0 && (
        <div className="mt-4 p-3 bg-gray-900 rounded border border-gray-700">
          <h3 className="text-sm font-bold text-green-400 mb-2">Detected Memory Regions</h3>
          <div className="space-y-1 text-xs">
            {memoryRegions.map((region, index) => (
              <div key={index} className="flex justify-between font-mono">
                <span className="text-gray-400">{region.name}:</span>
                <span className="text-green-400">
                  0x{region.start.toString(16).toUpperCase().padStart(8, '0')} -
                  0x{(region.start + region.size).toString(16).toUpperCase().padStart(8, '0')}
                  <span className="text-gray-500 ml-2">({(region.size / 1024).toFixed(0)}KB)</span>
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * ARM Binary Parser
 *
 * Specialized parser for ARM architectures, particularly Cortex-M series.
