  /**
   * Generate ARM-specific memory map
   */
  private generateArmMemoryMap(_info: BinaryInfo): unknown[] {
    const regions = [];

    // Typical STM32 memory layout
    regions.push({
      name: 'FLASH',
      start: 0x08000000,
      end: 0x08100000,
      size: 0x100000,
      type: 'flash',
      permissions: ['read', 'execute'],
      cacheable: true
    });

    regions.push({
      name: 'SRAM',
      start: 0x20000000,
      end: 0x20020000,
      size: 0x20000,
      type: 'ram',
      permissions: ['read', 'write', 'execute'],
