    regions.push({
      name: 'PERIPHERALS',
      start: 0x40000000,
      end: 0x60000000,
      size: 0x20000000,
      type: 'peripheral',
      permissions: ['read', 'write'],
      cacheable: false
    });

    regions.push({
      name: 'SYSTEM',
      start: 0xE0000000,
      end: 0xFFFFFFFF,
      size: 0x1FFFFFFF,
      type: 'peripheral',
      permissions: ['read', 'write'],
