/**
 * Basic Block Analyzer
 *
 * Identifies basic blocks from disassembled instructions.
 * A basic block is a straight-line code sequence with:
 * - One entry point (start)
 * - One exit point (end)
 * - No branches in the middle
 */

import type { DisassembledInstruction } from '../arm/ArmDisassembler';
import {
  BlockType,
  EdgeType
} from './types';
import type {
  BasicBlock,
  BlockAnalysisOptions,
  CFGEdge
} from './types';

export class BasicBlockAnalyzer {
  private options: BlockAnalysisOptions;

  constructor(options: BlockAnalysisOptions) {
    this.options = options;
  }

  /**
   * Identify basic blocks from disassembled instructions
   *
   * Algorithm:
   * 1. Find all block start addresses:
   *    - First instruction
   *    - Branch targets
   *    - Instructions after branches
   * 2. Split instructions into blocks at start addresses
   * 3. Classify each block by its terminating instruction
   * 4. Build edge connections between blocks
   */
  identifyBasicBlocks(instructions: DisassembledInstruction[]): BasicBlock[] {
    if (instructions.length === 0) {
      return [];
    }

    // Step 1: Identify block boundaries
    const blockStarts = this.findBlockStarts(instructions);

    // Step 2: Build basic blocks
    const blocks = this.buildBlocks(instructions, blockStarts);

    // Step 3: Classify blocks and build edges
    this.classifyBlocks(blocks, instructions);

    // Step 4: Connect blocks with edges
    this.buildEdges(blocks);

    return blocks;
  }

  /**
   * Find all addresses that start a basic block
   */
  private findBlockStarts(instructions: DisassembledInstruction[]): Set<number> {
    const starts = new Set<number>();

    // First instruction always starts a block
    starts.add(instructions[0].address);

    for (const inst of instructions) {
      // Branch target starts a new block
      if (inst.isBranch && inst.branchTarget !== undefined) {
        starts.add(inst.branchTarget);
      }

      // Instruction after branch starts a new block (fall-through)
      if (inst.isBranch) {
        const nextAddr = inst.address + inst.size;
        starts.add(nextAddr);
      }

      // Instruction after call may start new block (if call returns)
      if (this.isCallInstruction(inst)) {
        const nextAddr = inst.address + inst.size;
        starts.add(nextAddr);
      }
    }

    return starts;
  }

  /**
   * Build basic blocks by splitting at block start addresses
   */
  private buildBlocks(
    instructions: DisassembledInstruction[],
    blockStarts: Set<number>
  ): BasicBlock[] {
    const blocks: BasicBlock[] = [];
    let currentBlock: DisassembledInstruction[] = [];
    let blockStartAddr = instructions[0].address;

    for (let i = 0; i < instructions.length; i++) {
      const inst = instructions[i];

      // Check if this address starts a new block (and we have a current block)
      if (blockStarts.has(inst.address) && currentBlock.length > 0) {
        // Finalize current block
        blocks.push(this.createBlock(currentBlock, blockStartAddr));

        // Start new block
        currentBlock = [inst];
        blockStartAddr = inst.address;
      } else {
        // Add to current block
        currentBlock.push(inst);
      }
    }

    // Don't forget last block
    if (currentBlock.length > 0) {
      blocks.push(this.createBlock(currentBlock, blockStartAddr));
    }

    return blocks;
  }

  /**
   * Create a basic block from instructions
   */
  private createBlock(
    instructions: DisassembledInstruction[],
    startAddr: number
  ): BasicBlock {
    const lastInst = instructions[instructions.length - 1];

    return {
      id: `0x${startAddr.toString(16).toUpperCase().padStart(8, '0')}`,
      startAddress: startAddr,
      endAddress: lastInst.address,
      instructions,
      type: BlockType.NORMAL,  // Will be classified later
      predecessors: [],
      successors: [],
      edges: []
    };
  }

  /**
   * Classify blocks based on their terminating instructions
   */
  private classifyBlocks(
    blocks: BasicBlock[],
    _allInstructions: DisassembledInstruction[]
  ): void {
    // Mark entry block
    if (blocks.length > 0) {
      blocks[0].type = BlockType.ENTRY;
    }

    for (const block of blocks) {
      if (block.type === BlockType.ENTRY && blocks.length === 1) {
        // Single block - keep as entry
        continue;
      }

      const lastInst = block.instructions[block.instructions.length - 1];
      const blockType = this.classifyBlockType(lastInst);

      // Don't override ENTRY type unless it's also a return
      if (block.type !== BlockType.ENTRY || blockType === BlockType.RETURN) {
        block.type = blockType;
      }
    }
  }

  /**
   * Classify block type based on terminating instruction
   */
  private classifyBlockType(inst: DisassembledInstruction): BlockType {
    const mnemonic = inst.mnemonic.toLowerCase();

    // Return instructions
    if (mnemonic === 'bx' && inst.operands.toLowerCase().includes('lr')) {
      return BlockType.RETURN;
    }
    if (mnemonic === 'pop' && inst.operands.toLowerCase().includes('pc')) {
      return BlockType.RETURN;
    }

    // Call instructions
    if (mnemonic === 'bl' || mnemonic === 'blx') {
      return BlockType.CALL;
    }

    // Conditional branches
    if (inst.isBranch && mnemonic !== 'b' && mnemonic.startsWith('b')) {
      return BlockType.CONDITIONAL;
    }

    // Unconditional branch with no target = dead end
    if (mnemonic === 'b' && inst.branchTarget === undefined) {
      return BlockType.EXIT;
    }

    return BlockType.NORMAL;
  }

  /**
   * Build edges between blocks based on control flow
   */
  private buildEdges(blocks: BasicBlock[]): void {
    // Create address-to-block mapping for fast lookup
    const addrToBlock = new Map<number, BasicBlock>();
    for (const block of blocks) {
      addrToBlock.set(block.startAddress, block);
    }

    for (const block of blocks) {
      const lastInst = block.instructions[block.instructions.length - 1];

      // Handle branch instructions
      if (lastInst.isBranch && lastInst.branchTarget !== undefined) {
        const targetBlock = addrToBlock.get(lastInst.branchTarget);

        if (targetBlock) {
          const edgeType = this.determineEdgeType(lastInst, true);
          this.addEdge(block, targetBlock, edgeType, lastInst);
        }
      }

      // Handle fall-through (non-unconditional branches and normal flow)
      if (!this.isUnconditionalExit(lastInst)) {
        const nextAddr = lastInst.address + lastInst.size;
        const nextBlock = addrToBlock.get(nextAddr);

        if (nextBlock) {
          const edgeType = this.determineEdgeType(lastInst, false);
          this.addEdge(block, nextBlock, edgeType, lastInst);
        }
      }
    }
  }

  /**
   * Determine edge type based on instruction
   */
  private determineEdgeType(
    inst: DisassembledInstruction,
    isBranchTarget: boolean
  ): EdgeType {
    const mnemonic = inst.mnemonic.toLowerCase();

    // Call edge
    if (mnemonic === 'bl' || mnemonic === 'blx') {
      return EdgeType.CALL;
    }

    // Conditional branch
    if (inst.isBranch && mnemonic.startsWith('b') && mnemonic !== 'b') {
      return isBranchTarget ? EdgeType.CONDITIONAL_TRUE : EdgeType.CONDITIONAL_FALSE;
    }

    // Unconditional
    return EdgeType.UNCONDITIONAL;
  }

  /**
   * Add edge between blocks
   */
  private addEdge(
    from: BasicBlock,
    to: BasicBlock,
    type: EdgeType,
    inst: DisassembledInstruction
  ): void {
    // Don't add duplicate edges
    if (from.successors.includes(to.id)) {
      return;
    }

    const edge: CFGEdge = {
      target: to.id,
      type,
      condition: this.extractCondition(inst, type)
    };

    from.edges.push(edge);
    from.successors.push(to.id);
    to.predecessors.push(from.id);
  }

  /**
   * Extract condition string from conditional branch
   */
  private extractCondition(
    inst: DisassembledInstruction,
    edgeType: EdgeType
  ): string | undefined {
    if (edgeType !== EdgeType.CONDITIONAL_TRUE &&
        edgeType !== EdgeType.CONDITIONAL_FALSE) {
      return undefined;
    }

    const mnemonic = inst.mnemonic.toLowerCase();

    // ARM condition codes
    const conditionMap: Record<string, string> = {
      'beq': 'Z==1',
      'bne': 'Z==0',
      'bcs': 'C==1',
      'bcc': 'C==0',
      'bmi': 'N==1',
      'bpl': 'N==0',
      'bvs': 'V==1',
      'bvc': 'V==0',
      'bhi': 'C==1 && Z==0',
      'bls': 'C==0 || Z==1',
      'bge': 'N==V',
      'blt': 'N!=V',
      'bgt': 'Z==0 && N==V',
      'ble': 'Z==1 || N!=V'
    };

    const condition = conditionMap[mnemonic];

    if (edgeType === EdgeType.CONDITIONAL_FALSE && condition) {
      return `!(${condition})`;
    }

    return condition;
  }

  /**
   * Check if instruction is a call
   */
  private isCallInstruction(inst: DisassembledInstruction): boolean {
    const mnemonic = inst.mnemonic.toLowerCase();
    return mnemonic === 'bl' || mnemonic === 'blx';
  }

  /**
   * Check if instruction is an unconditional exit (no fall-through)
   */
  private isUnconditionalExit(inst: DisassembledInstruction): boolean {
    const mnemonic = inst.mnemonic.toLowerCase();

    // Unconditional branch
    if (mnemonic === 'b' && inst.branchTarget !== undefined) {
      return true;
    }

    // Return instructions
    if (mnemonic === 'bx' && inst.operands.toLowerCase().includes('lr')) {
      return true;
    }
    if (mnemonic === 'pop' && inst.operands.toLowerCase().includes('pc')) {
      return true;
    }

    return false;
  }
}

/**
 * CFG Layout Engine
 *
 * Computes visual layout for control flow graphs using hierarchical (Sugiyama) algorithm.
 * Produces coordinates for blocks and edge routing for visualization.
 */

import {
  EdgeType
} from './types';
import type {
  ControlFlowGraph,
  CFGLayout,
  BlockLayout,
  EdgeLayout,
  LayoutOptions,
  Point,
  BasicBlock
} from './types';

export class CFGLayoutEngine {
  private options: LayoutOptions;

  constructor(options: LayoutOptions) {
    this.options = options;
  }

  /**
   * Compute layout for CFG
   *
   * Uses Sugiyama hierarchical layout algorithm:
   * 1. Layer Assignment - assign blocks to horizontal layers
   * 2. Crossing Reduction - minimize edge crossings
   * 3. Coordinate Assignment - assign final X,Y coordinates
   * 4. Edge Routing - compute edge paths
   */
  computeLayout(cfg: ControlFlowGraph): CFGLayout {
    if (cfg.blocks.size === 0) {
      return {
        blocks: new Map(),
        edges: [],
        bounds: { width: 0, height: 0 }
      };
    }

    // Phase 1: Assign blocks to layers (levels)
    const layers = this.assignLayers(cfg);

    // Phase 2: Order blocks within layers to reduce crossings
    this.reduceCrossings(layers, cfg);

    // Phase 3: Assign coordinates
    const blockLayouts = this.assignCoordinates(layers);

    // Phase 4: Route edges
    const edgeLayouts = this.routeEdges(blockLayouts, cfg);

    // Calculate bounds
    const bounds = this.calculateBounds(blockLayouts);

    return {
      blocks: blockLayouts,
      edges: edgeLayouts,
      bounds
    };
  }

  /**
   * Phase 1: Assign blocks to layers using longest-path layering
   *
   * Each block is assigned to a layer (vertical level) based on
   * the longest path from the entry block.
   */
  private assignLayers(cfg: ControlFlowGraph): Map<number, string[]> {
    const layers = new Map<number, string[]>();
    const levels = new Map<string, number>();

    // BFS to assign levels
    const queue: Array<{ id: string; level: number }> = [
      { id: cfg.entryBlock, level: 0 }
    ];
    const visited = new Set<string>();

    while (queue.length > 0) {
      const { id, level } = queue.shift()!;

      if (visited.has(id)) {
        // Update level if we found a longer path
        const currentLevel = levels.get(id) ?? -1;
        if (level > currentLevel) {
          levels.set(id, level);
        }
        continue;
      }

      visited.add(id);
      levels.set(id, level);

      const block = cfg.blocks.get(id);
      if (!block) continue;

      // Add successors to queue
      for (const successorId of block.successors) {
        queue.push({ id: successorId, level: level + 1 });
      }
    }

    // Group blocks by level
    for (const [id, level] of levels) {
      if (!layers.has(level)) {
        layers.set(level, []);
      }
      layers.get(level)!.push(id);
    }

    return layers;
  }

  /**
   * Phase 2: Reduce edge crossings using barycentric heuristic
   *
   * Reorder blocks within each layer to minimize edge crossings.
   * Uses iterative improvement with barycentric positioning.
   */
  private reduceCrossings(layers: Map<number, string[]>, cfg: ControlFlowGraph): void {
    const maxIterations = 10;

    for (let iter = 0; iter < maxIterations; iter++) {
      let improved = false;

      // Forward pass - adjust based on predecessors
      const sortedLevels = Array.from(layers.keys()).sort((a, b) => a - b);

      for (const level of sortedLevels) {
        const layer = layers.get(level)!;
        if (layer.length <= 1) continue;

        // Calculate barycenter for each block
        const barycenters = new Map<string, number>();

        for (const blockId of layer) {
          const block = cfg.blocks.get(blockId);
          if (!block || block.predecessors.length === 0) {
            barycenters.set(blockId, layer.indexOf(blockId));
            continue;
          }

          // Average position of predecessors
          let sum = 0;
          let count = 0;

          for (const predId of block.predecessors) {
            const predLevel = this.getBlockLevel(predId, layers);
            if (predLevel !== undefined && predLevel < level) {
              const predLayer = layers.get(predLevel)!;
              sum += predLayer.indexOf(predId);
              count++;
            }
          }

          barycenters.set(blockId, count > 0 ? sum / count : layer.indexOf(blockId));
        }

        // Sort layer by barycenter
        const newOrder = [...layer].sort((a, b) => {
          return (barycenters.get(a) ?? 0) - (barycenters.get(b) ?? 0);
        });

        // Check if order changed
        if (newOrder.some((id, i) => id !== layer[i])) {
          layers.set(level, newOrder);
          improved = true;
        }
      }

      if (!improved) break;
    }
  }

  /**
   * Get the level of a block
   */
  private getBlockLevel(blockId: string, layers: Map<number, string[]>): number | undefined {
    for (const [level, layer] of layers) {
      if (layer.includes(blockId)) {
        return level;
      }
    }
    return undefined;
  }

  /**
   * Phase 3: Assign X,Y coordinates to blocks
   */
  private assignCoordinates(layers: Map<number, string[]>): Map<string, BlockLayout> {
    const layouts = new Map<string, BlockLayout>();
    const { blockWidth, blockHeight, horizontalSpacing, verticalSpacing } = this.options;

    const sortedLevels = Array.from(layers.keys()).sort((a, b) => a - b);

    for (const level of sortedLevels) {
      const layer = layers.get(level)!;
      const y = level * (blockHeight + verticalSpacing);

      // Center blocks horizontally
      const totalWidth = layer.length * blockWidth + (layer.length - 1) * horizontalSpacing;
      let startX = 0;

      if (this.options.compactLayout) {
        startX = 0;
      } else {
        // Center the layer
        startX = Math.max(0, -totalWidth / 2);
      }

      for (let i = 0; i < layer.length; i++) {
        const blockId = layer[i];
        const x = startX + i * (blockWidth + horizontalSpacing);

        layouts.set(blockId, {
          id: blockId,
          x,
          y,
          width: blockWidth,
          height: blockHeight,
          level
        });
      }
    }

    return layouts;
  }

  /**
   * Phase 4: Route edges between blocks
   *
   * Creates edge paths with bezier curves for smooth visualization.
   */
  private routeEdges(
    blockLayouts: Map<string, BlockLayout>,
    cfg: ControlFlowGraph
  ): EdgeLayout[] {
    const edges: EdgeLayout[] = [];

    for (const [blockId, block] of cfg.blocks) {
      const fromLayout = blockLayouts.get(blockId);
      if (!fromLayout) continue;

      for (const edge of block.edges) {
        const toLayout = blockLayouts.get(edge.target);
        if (!toLayout) continue;

        const edgeLayout = this.createEdgeLayout(
          fromLayout,
          toLayout,
          edge.type,
          block,
          cfg
        );

        edges.push(edgeLayout);
      }
    }

    return edges;
  }

  /**
   * Create edge layout with routing points
   */
  private createEdgeLayout(
    from: BlockLayout,
    to: BlockLayout,
    type: EdgeType,
    _fromBlock: BasicBlock,
    _cfg: ControlFlowGraph
  ): EdgeLayout {
    // Calculate edge color
    const color = this.getEdgeColor(type);

    // Calculate connection points
    const fromPoint = this.getBlockExitPoint(from);
    const toPoint = this.getBlockEntryPoint(to);

    // Check if this is a back-edge (loop)
    const isBackEdge = to.level <= from.level;

    // Generate bezier control points
    const points = this.generateEdgePath(fromPoint, toPoint, isBackEdge, from, to);

    return {
      from: from.id,
      to: to.id,
      type,
      points,
      color,
      isBackEdge
    };
  }

  /**
   * Get block exit point (bottom center)
   */
  private getBlockExitPoint(layout: BlockLayout): Point {
    return {
      x: layout.x + layout.width / 2,
      y: layout.y + layout.height
    };
  }

  /**
   * Get block entry point (top center)
   */
  private getBlockEntryPoint(layout: BlockLayout): Point {
    return {
      x: layout.x + layout.width / 2,
      y: layout.y
    };
  }

  /**
   * Generate edge path with bezier control points
   */
  private generateEdgePath(
    from: Point,
    to: Point,
    isBackEdge: boolean,
    fromLayout: BlockLayout,
    toLayout: BlockLayout
  ): Point[] {
    if (isBackEdge) {
      // Back-edges curve around to the side
      const side = fromLayout.x < toLayout.x ? -1 : 1;
      const offset = 50 * side;

      return [
        from,
        { x: from.x + offset, y: from.y + 30 },
        { x: to.x + offset, y: to.y - 30 },
        to
      ];
    }

    // Normal forward edge
    const dy = to.y - from.y;

    if (Math.abs(from.x - to.x) < 10) {
      // Straight vertical line
      return [from, to];
    }

    // Curved edge
    const controlOffset = Math.min(dy * 0.5, 50);

    return [
      from,
      { x: from.x, y: from.y + controlOffset },
      { x: to.x, y: to.y - controlOffset },
      to
    ];
  }

  /**
   * Get edge color based on type
   */
  private getEdgeColor(type: EdgeType): string {
    const colors = {
      [EdgeType.UNCONDITIONAL]: '#9ca3af',      // Gray
      [EdgeType.CONDITIONAL_TRUE]: '#10b981',   // Green
      [EdgeType.CONDITIONAL_FALSE]: '#ef4444',  // Red
      [EdgeType.CALL]: '#a855f7',               // Purple
      [EdgeType.RETURN]: '#ec4899'              // Pink
    };

    return colors[type] || '#9ca3af';
  }

  /**
   * Calculate bounding box for layout
   */
  private calculateBounds(blockLayouts: Map<string, BlockLayout>): { width: number; height: number } {
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;

    for (const [, layout] of blockLayouts) {
      minX = Math.min(minX, layout.x);
      minY = Math.min(minY, layout.y);
      maxX = Math.max(maxX, layout.x + layout.width);
      maxY = Math.max(maxY, layout.y + layout.height);
    }

    const padding = 50;

    return {
      width: maxX - minX + padding * 2,
      height: maxY - minY + padding * 2
    };
  }
}

/**
 * Control Flow Analyzer
 *
 * Builds complete control flow graphs from basic blocks.
 * Performs additional analysis like:
 * - Cyclomatic complexity calculation
 * - Loop detection
 * - Dominator tree construction
 * - Unreachable code detection
 */

import {
  BlockType
} from './types';
import type {
  BasicBlock,
  ControlFlowGraph,
  CFGAnalysisResult,
  BlockAnalysisOptions,
  Loop
} from './types';

export class ControlFlowAnalyzer {
  private options: BlockAnalysisOptions;

  constructor(options: BlockAnalysisOptions) {
    this.options = options;
  }

  /**
   * Build complete CFG from basic blocks with full analysis
   */
  buildCFG(blocks: BasicBlock[]): CFGAnalysisResult {
    const startTime = Date.now();
    const warnings: string[] = [];
    const errors: string[] = [];

    if (blocks.length === 0) {
      errors.push('No basic blocks provided');
      return {
        cfg: this.createEmptyCFG(),
        warnings,
        errors,
        statistics: {
          analysisTimeMs: Date.now() - startTime,
          blocksCreated: 0,
          edgesCreated: 0
        }
      };
    }

    // Build CFG structure
    const cfg = this.createCFG(blocks);

    // Detect unreachable blocks
    if (this.options.detectUnreachable) {
      const unreachable = this.detectUnreachableBlocks(cfg);
      if (unreachable.length > 0) {
        warnings.push(`Found ${unreachable.length} unreachable blocks`);
        unreachable.forEach(id => {
          const block = cfg.blocks.get(id);
          if (block) {
            block.type = BlockType.UNREACHABLE;
          }
        });
      }
    }

    // Detect loops
    if (this.options.detectLoops) {
      cfg.loops = this.detectLoops(cfg);
      if (cfg.loops.length > 0) {
        cfg.metadata.maxLoopDepth = Math.max(...cfg.loops.map(l => l.depth));
      }
    }

    // Calculate cyclomatic complexity: E - N + 2P
    // E = edges, N = nodes, P = connected components (usually 1)
    cfg.metadata.cyclomaticComplexity = this.calculateCyclomaticComplexity(cfg);

    const analysisTimeMs = Date.now() - startTime;

    return {
      cfg,
      warnings,
      errors,
      statistics: {
        analysisTimeMs,
        blocksCreated: blocks.length,
        edgesCreated: this.countEdges(cfg)
      }
    };
  }

  /**
   * Create CFG structure from blocks
   */
  private createCFG(blocks: BasicBlock[]): ControlFlowGraph {
    const blockMap = new Map<string, BasicBlock>();
    const exitBlocks: string[] = [];

    // Add all blocks to map
    for (const block of blocks) {
      blockMap.set(block.id, block);

      // Identify exit blocks (no successors or return blocks)
      if (block.successors.length === 0 || block.type === BlockType.RETURN) {
        exitBlocks.push(block.id);
      }
    }

    const firstBlock = blocks[0];
    const lastBlock = blocks[blocks.length - 1];

    return {
      blocks: blockMap,
      entryBlock: firstBlock.id,
      exitBlocks,
      functionStart: firstBlock.startAddress,
      functionEnd: lastBlock.endAddress,
      metadata: {
        architecture: this.options.architecture,
        totalInstructions: blocks.reduce((sum, b) => sum + b.instructions.length, 0),
        totalBlocks: blocks.length,
        cyclomaticComplexity: 1,  // Will be calculated
        maxLoopDepth: 0            // Will be calculated if loops detected
      }
    };
  }

  /**
   * Create empty CFG for error cases
   */
  private createEmptyCFG(): ControlFlowGraph {
    return {
      blocks: new Map(),
      entryBlock: '',
      exitBlocks: [],
      functionStart: 0,
      functionEnd: 0,
      metadata: {
        architecture: this.options.architecture,
        totalInstructions: 0,
        totalBlocks: 0,
        cyclomaticComplexity: 0,
        maxLoopDepth: 0
      }
    };
  }

  /**
   * Detect unreachable blocks using depth-first search
   */
  private detectUnreachableBlocks(cfg: ControlFlowGraph): string[] {
    const reachable = new Set<string>();
    const visited = new Set<string>();

    // DFS from entry block
    const dfs = (blockId: string) => {
      if (visited.has(blockId)) return;
      visited.add(blockId);
      reachable.add(blockId);

      const block = cfg.blocks.get(blockId);
      if (!block) return;

      for (const successorId of block.successors) {
        dfs(successorId);
      }
    };

    dfs(cfg.entryBlock);

    // Find unreachable blocks
    const unreachable: string[] = [];
    for (const [blockId] of cfg.blocks) {
      if (!reachable.has(blockId)) {
        unreachable.push(blockId);
      }
    }

    return unreachable;
  }

  /**
   * Detect loops using back-edge detection
   *
   * A back-edge is an edge whose target dominates its source.
   * This indicates a loop structure.
   */
  private detectLoops(cfg: ControlFlowGraph): Loop[] {
    const loops: Loop[] = [];
    const visited = new Set<string>();
    const inStack = new Set<string>();

    // DFS to find back edges
    const dfs = (blockId: string, path: string[]): void => {
      if (visited.has(blockId)) {
        // Found a back edge if block is in current path
        if (inStack.has(blockId)) {
          const loop = this.extractLoop(blockId, path[path.length - 1], path, cfg);
          if (loop) {
            loops.push(loop);
          }
        }
        return;
      }

      visited.add(blockId);
      inStack.add(blockId);
      path.push(blockId);

      const block = cfg.blocks.get(blockId);
      if (block) {
        for (const successorId of block.successors) {
          dfs(successorId, [...path]);
        }
      }

      inStack.delete(blockId);
    };

    dfs(cfg.entryBlock, []);

    // Assign loop depths
    this.assignLoopDepths(loops);

    return loops;
  }

  /**
   * Extract loop structure from back edge
   */
  private extractLoop(
    header: string,
    backedge: string,
    path: string[],
    _cfg: ControlFlowGraph
  ): Loop | null {
    // Find all blocks in loop body
    const headerIndex = path.indexOf(header);
    if (headerIndex === -1) return null;

    const loopBlocks = new Set<string>(path.slice(headerIndex));

    return {
      header,
      backedge,
      blocks: loopBlocks,
      depth: 1  // Will be calculated later
    };
  }

  /**
   * Assign nesting depths to loops
   */
  private assignLoopDepths(loops: Loop[]): void {
    // Sort loops by size (smaller loops are more nested)
    loops.sort((a, b) => a.blocks.size - b.blocks.size);

    for (let i = 0; i < loops.length; i++) {
      const loop = loops[i];
      let maxParentDepth = 0;

      // Find parent loops (loops that contain this loop)
      for (let j = i + 1; j < loops.length; j++) {
        const parentLoop = loops[j];
        if (parentLoop.blocks.has(loop.header)) {
          maxParentDepth = Math.max(maxParentDepth, parentLoop.depth);
        }
      }

      loop.depth = maxParentDepth + 1;
    }
  }

  /**
   * Calculate cyclomatic complexity
   *
   * Formula: M = E - N + 2P
   * Where:
   * - E = number of edges
   * - N = number of nodes
   * - P = number of connected components (usually 1)
   */
  private calculateCyclomaticComplexity(cfg: ControlFlowGraph): number {
    const E = this.countEdges(cfg);
    const N = cfg.blocks.size;
    const P = 1;  // Assuming single connected component

    return E - N + 2 * P;
  }

  /**
   * Count total edges in CFG
   */
  private countEdges(cfg: ControlFlowGraph): number {
    let count = 0;
    for (const [, block] of cfg.blocks) {
      count += block.successors.length;
    }
    return count;
  }

  /**
   * Build dominator tree (optional advanced analysis)
   *
   * A block A dominates block B if all paths from entry to B go through A.
   * This is useful for advanced optimizations and understanding control flow.
   */
  buildDominatorTree(cfg: ControlFlowGraph): Map<string, string[]> {
    const dominators = new Map<string, Set<string>>();

    // Initialize: entry dominates itself, all others dominated by everyone
    const allBlocks = new Set(cfg.blocks.keys());
    dominators.set(cfg.entryBlock, new Set([cfg.entryBlock]));

    for (const [blockId] of cfg.blocks) {
      if (blockId !== cfg.entryBlock) {
        dominators.set(blockId, new Set(allBlocks));
      }
    }

    // Iterative algorithm
    let changed = true;
    while (changed) {
      changed = false;

      for (const [blockId, block] of cfg.blocks) {
        if (blockId === cfg.entryBlock) continue;

        // New dominators = {block} ∪ (∩ dominators of predecessors)
        const newDominators = new Set([blockId]);

        if (block.predecessors.length > 0) {
          // Start with first predecessor's dominators
          const firstPred = dominators.get(block.predecessors[0]);
          if (firstPred) {
            for (const dom of firstPred) {
              newDominators.add(dom);
            }
          }

          // Intersect with other predecessors
          for (let i = 1; i < block.predecessors.length; i++) {
            const predDom = dominators.get(block.predecessors[i]);
            if (!predDom) continue;

            // Remove dominators not in this predecessor
            for (const dom of newDominators) {
              if (!predDom.has(dom) && dom !== blockId) {
                newDominators.delete(dom);
              }
            }
          }
        }

        // Check if changed
        const oldDominators = dominators.get(blockId)!;
        if (newDominators.size !== oldDominators.size ||
            ![...newDominators].every(d => oldDominators.has(d))) {
          dominators.set(blockId, newDominators);
          changed = true;
        }
      }
    }

    // Convert to array map
    const dominatorTree = new Map<string, string[]>();
    for (const [blockId, doms] of dominators) {
      dominatorTree.set(blockId, Array.from(doms));
    }

    return dominatorTree;
  }
}

/**
 * Black Magic Probe Specific Commands
 *
 * High-level command wrappers for Black Magic Probe monitor commands
 * and GDB operations. These methods build on the GDB client to provide
 * probe-specific functionality.
 */

import { PowerState } from './types';
import type { Target, BmpVersion } from './types';

/**
 * Black Magic Probe command builder and parser
 */
export class BlackMagicCommands {
  /**
   * Build a monitor command
   *
   * Monitor commands are sent to the debug probe itself, not the target.
   * Format: qRcmd,<hex-encoded-command>
   *
   * @param command - Monitor command string
   * @returns GDB command string
   */
  static buildMonitorCommand(command: string): string {
    // Convert command to hex
    const hexCommand = Array.from(command)
      .map(c => c.charCodeAt(0).toString(16).padStart(2, '0'))
      .join('');
    return `qRcmd,${hexCommand}`;
  }

  /**
   * Decode hex-encoded monitor response
   *
   * Monitor command responses are hex-encoded strings.
   *
   * @param hexData - Hex-encoded response
   * @returns Decoded string
   */
  static decodeMonitorResponse(hexData: string): string {
    let result = '';
    for (let i = 0; i < hexData.length; i += 2) {
      const byte = parseInt(hexData.substring(i, i + 2), 16);
      result += String.fromCharCode(byte);
    }
    return result;
  }

  /**
   * Build SWD scan command
   *
   * Scans for targets using Serial Wire Debug interface.
   *
   * @returns Monitor command
   */
  static buildSwdScan(): string {
    return this.buildMonitorCommand('swdp_scan');
  }

  /**
   * Build JTAG scan command
   *
   * Scans for targets using JTAG interface.
   *
   * @returns Monitor command
   */
  static buildJtagScan(): string {
    return this.buildMonitorCommand('jtag_scan');
  }

  /**
   * Build target power enable command
   *
   * @returns Monitor command
   */
  static buildPowerEnable(): string {
    return this.buildMonitorCommand('tpwr enable');
  }

  /**
   * Build target power disable command
   *
   * @returns Monitor command
   */
  static buildPowerDisable(): string {
    return this.buildMonitorCommand('tpwr disable');
  }

  /**
   * Build version query command
   *
   * @returns Monitor command
   */
  static buildVersionQuery(): string {
    return this.buildMonitorCommand('version');
  }

  /**
   * Build target reset command
