// STOP REPLY PARSER
// ============================================================================

/**
 * Parser for stop reply packets
 */
export class StopReplyParser {
  /**
   * Signal number to stop reason mapping
   */
  private static readonly SIGNAL_TO_REASON: Record<number, StopReason> = {
    2: StopReason.SIGNAL,        // SIGINT - Ctrl+C
    5: StopReason.BREAKPOINT,    // SIGTRAP - Breakpoint/watchpoint
    11: StopReason.SIGNAL,       // SIGSEGV - Memory fault
  };

  /**
   * Parse detailed stop reply from 'T' packet
   *
   * Format: Txx[key:value;]...
   * - xx: Signal number (2 hex digits)
   * - key:value pairs separated by semicolons
   *
   * Common keys:
   * - thread: Thread ID
   * - core: Core number
   * - watch/rwatch/awatch: Watchpoint address
   * - swbreak: Software breakpoint indicator
   * - hwbreak: Hardware breakpoint indicator
   * - NN: Register value (NN is hex register number)
   *
   * Algorithm:
   * 1. Extract signal number from first 2 hex digits
   * 2. Parse key:value pairs
   * 3. Determine stop reason from signal and keys
   * 4. Extract thread, core, watchpoint info
   * 5. Parse any included register values
   *
   * @param packet - Raw 'T' packet data
   * @returns Parsed stop reply or error
   *
   * @example
   * // T05thread:01;swbreak:;0f:12345678;
   * const result = StopReplyParser.parseDetailed('T05thread:01;swbreak:;');
   * if (result.success) {
   *   console.log(`Stopped: ${result.data.reason}, signal ${result.data.signal}`);
   * }
   */
  static parseDetailed(packet: string): ParseResult<StopReplyDetailed> {
    try {
      // Step 1: Validate packet format
      if (!packet.startsWith('T')) {
        return { success: false, error: 'Not a T packet', raw: packet };
      }

      if (packet.length < 3) {
        return { success: false, error: 'T packet too short', raw: packet };
      }

      // Step 2: Extract signal number
      const signalHex = packet.substring(1, 3);
      if (!/^[0-9a-fA-F]{2}$/.test(signalHex)) {
        return { success: false, error: 'Invalid signal hex', raw: packet };
      }

      const signal = parseInt(signalHex, 16);

      // Step 3: Parse key:value pairs
      const rawInfo = new Map<string, string>();
      const remainder = packet.substring(3);

      if (remainder.length > 0) {
        const pairs = remainder.split(';').filter(p => p.length > 0);

        for (const pair of pairs) {
          const colonIndex = pair.indexOf(':');
          if (colonIndex === -1) {
            // Key without value (e.g., "swbreak")
            rawInfo.set(pair, '');
          } else {
            const key = pair.substring(0, colonIndex);
            const value = pair.substring(colonIndex + 1);
            rawInfo.set(key, value);
          }
        }
      }

      // Step 4: Determine stop reason
      let reason = this.SIGNAL_TO_REASON[signal] || StopReason.UNKNOWN;

      if (rawInfo.has('swbreak') || rawInfo.has('hwbreak')) {
        reason = StopReason.BREAKPOINT;
      } else if (rawInfo.has('watch') || rawInfo.has('rwatch') || rawInfo.has('awatch')) {
        reason = StopReason.WATCHPOINT;
      }

      // Step 5: Extract structured data
      const result: StopReplyDetailed = {
        signal,
        reason,
        rawInfo
      };

      // Thread ID
      if (rawInfo.has('thread')) {
        const threadValue = rawInfo.get('thread')!;
        if (threadValue.length > 0) {
          result.thread = parseInt(threadValue, 16);
        }
      }

      // Core ID
      if (rawInfo.has('core')) {
        const coreValue = rawInfo.get('core')!;
        if (coreValue.length > 0) {
          result.core = parseInt(coreValue, 16);
        }
      }

      // Watchpoint address
      for (const key of ['watch', 'rwatch', 'awatch']) {
        if (rawInfo.has(key)) {
          const addrValue = rawInfo.get(key)!;
          if (addrValue.length > 0) {
            result.watchAddr = parseInt(addrValue, 16);
            break;
          }
        }
      }

      // Step 6: Parse register values
      // Register values have numeric keys (hex register number)
      const registers = new Map<number, number>();

      for (const [key, value] of rawInfo.entries()) {
        if (/^[0-9a-fA-F]+$/.test(key) && value.length > 0) {
          const regNum = parseInt(key, 16);

          // Parse register value (little-endian)
          const bytes = value.match(/.{2}/g);
          if (bytes) {
            const leValue = bytes.reverse().join('');
            const regValue = parseInt(leValue, 16);
            registers.set(regNum, regValue);
          }
        }
      }

      if (registers.size > 0) {
        result.registers = registers;
      }

      return { success: true, data: result };
    } catch (error) {
      return {
        success: false,
        error: `Stop reply parse error: ${(error as Error).message}`,
        raw: packet
      };
    }
  }

  /**
   * Parse simple stop reply from 'S' packet
   *
   * Format: Sxx
   * - xx: Signal number only
   *
   * @param packet - Raw 'S' packet data
   * @returns Parsed stop reply or error
   *
   * @example
   * // S05 (SIGTRAP)
   * const result = StopReplyParser.parseSimple('S05');
   * if (result.success) {
   *   console.log(`Signal: ${result.data.signal}`);
   * }
   */
  static parseSimple(packet: string): ParseResult<StopReplySimple> {
    try {
      if (!packet.startsWith('S')) {
        return { success: false, error: 'Not an S packet', raw: packet };
      }

      if (packet.length !== 3) {
        return { success: false, error: 'S packet must be exactly 3 characters', raw: packet };
      }

      const signalHex = packet.substring(1, 3);
      if (!/^[0-9a-fA-F]{2}$/.test(signalHex)) {
        return { success: false, error: 'Invalid signal hex', raw: packet };
      }

      const signal = parseInt(signalHex, 16);
      const reason = this.SIGNAL_TO_REASON[signal] || StopReason.UNKNOWN;

      return {
        success: true,
        data: { signal, reason }
      };
    } catch (error) {
      return {
        success: false,
        error: `Stop reply parse error: ${(error as Error).message}`,
        raw: packet
      };
    }
  }

  /**
   * Parse any stop reply (auto-detects T or S packet)
   *
   * @param packet - Raw stop reply packet
   * @returns Parsed stop reply or error
   */
  static parse(packet: string): ParseResult<StopReply> {
    if (packet.startsWith('T')) {
      return this.parseDetailed(packet);
    } else if (packet.startsWith('S')) {
      return this.parseSimple(packet);
    } else {
      return { success: false, error: 'Not a stop reply packet (must start with T or S)', raw: packet };
    }
  }

  /**
   * Get human-readable signal name
   *
   * @param signal - Signal number
   * @returns Signal name
   */
  static getSignalName(signal: number): string {
    const names: Record<number, string> = {
      0: 'SIG0',
      2: 'SIGINT',
      5: 'SIGTRAP',
      11: 'SIGSEGV',
      15: 'SIGTERM',
    };
    return names[signal] || `SIG${signal}`;
  }
}

// ============================================================================
// BREAKPOINT PARSER
// ============================================================================

/**
 * Parser for breakpoint operation responses
 */
export class BreakpointParser {
  /**
   * Parse breakpoint insert response (Z command)
   *
   * Format: Z<type>,<addr>,<kind>
   * Response: OK (success) or E<nn> (error)
   *
   * @param response - Response packet
   * @param address - Breakpoint address
   * @param type - Breakpoint type (0-4)
   * @returns Breakpoint result
   *
   * @example
   * const result = BreakpointParser.parseInsert('OK', 0x08000000, 0);
   * console.log(`Breakpoint set: ${result.success}`);
   */
  static parseInsert(response: string, address: number, type: number): BreakpointResult {
    if (response === 'OK') {
      return {
        success: true,
        address,
        type
      };
    }

    // Parse error
    let error = 'Unknown error';
    if (response.startsWith('E')) {
      const code = response.substring(1);
      error = `Error code ${code}`;
    } else if (response === '') {
      error = 'Empty response (unsupported)';
    }

    return {
      success: false,
      address,
      type,
      error
    };
  }

  /**
   * Parse breakpoint remove response (z command)
   *
   * Format: z<type>,<addr>,<kind>
   * Response: OK (success) or E<nn> (error)
   *
   * @param response - Response packet
   * @param address - Breakpoint address
   * @param type - Breakpoint type (0-4)
   * @returns Breakpoint result
   */
  static parseRemove(response: string, address: number, type: number): BreakpointResult {
    // Same logic as insert
    return this.parseInsert(response, address, type);
  }

  /**
   * Get breakpoint type name
   *
   * @param type - Breakpoint type number
   * @returns Type name
   */
  static getTypeName(type: number): string {
    const names: Record<number, string> = {
      0: 'Software Breakpoint',
      1: 'Hardware Breakpoint',
      2: 'Write Watchpoint',
      3: 'Read Watchpoint',
      4: 'Access Watchpoint'
    };
    return names[type] || `Unknown (${type})`;
  }
}

// ============================================================================
// MONITOR PARSER
// ============================================================================

/**
 * Parser for monitor command responses
 */
export class MonitorParser {
  /**
   * Parse monitor command output
   *
   * Monitor commands return hex-encoded console output with 'O' prefix.
   * Multiple 'O' packets may be sent for long output.
   *
   * Format: OXXXXXXXX... (hex-encoded ASCII)
   *
   * Algorithm:
   * 1. Check for 'O' prefix
   * 2. Extract hex data after 'O'
   * 3. Decode hex pairs to ASCII characters
   *
   * @param packet - Response packet starting with 'O'
   * @returns Parsed monitor output or error
   *
   * @example
   * // O48656c6c6f (hex for "Hello")
   * const result = MonitorParser.parse('O48656c6c6f');
   * if (result.success) {
   *   console.log(result.data.output); // "Hello"
   * }
   */
  static parse(packet: string): ParseResult<MonitorResponse> {
    try {
      // Step 1: Validate prefix
      if (!packet.startsWith('O')) {
        return { success: false, error: 'Not a monitor output packet (must start with O)', raw: packet };
      }

      // Step 2: Extract hex data
      const hexData = packet.substring(1);

      if (hexData.length === 0) {
        return {
          success: true,
          data: { output: '', hex: '' }
        };
      }

      if (!/^[0-9a-fA-F]+$/.test(hexData)) {
        return { success: false, error: 'Invalid hex characters in monitor output', raw: packet };
      }

      if (hexData.length % 2 !== 0) {
        return { success: false, error: 'Odd number of hex digits in monitor output', raw: packet };
      }

      // Step 3: Decode hex to ASCII
      let output = '';
      for (let i = 0; i < hexData.length; i += 2) {
        const byte = parseInt(hexData.substring(i, i + 2), 16);
        output += String.fromCharCode(byte);
      }

      return {
        success: true,
        data: { output, hex: hexData }
      };
    } catch (error) {
      return {
        success: false,
        error: `Monitor output parse error: ${(error as Error).message}`,
        raw: packet
      };
    }
  }

  /**
   * Encode monitor command to hex for qRcmd
   *
   * @param command - ASCII command string
   * @returns Hex-encoded command
   */
  static encodeCommand(command: string): string {
    return Array.from(command)
      .map(c => c.charCodeAt(0).toString(16).padStart(2, '0'))
      .join('');
  }
}

// ============================================================================
// ERROR PARSER
// ============================================================================

/**
 * Parser for error responses
 */
export class ErrorParser {
  /**
   * Standard GDB error codes
   */
  private static readonly ERROR_MESSAGES: Record<number, string> = {
    0x00: 'No error',
    0x01: 'Generic error',
    0x02: 'Invalid memory address',
    0x03: 'Invalid register number',
    0x04: 'Not stopped',
    0x05: 'Not running',
    0x06: 'Invalid parameter',
    0x07: 'Permission denied',
    0x08: 'Not supported',
    0x09: 'Resource not available',
    0x0A: 'Invalid thread',
    0x0B: 'Invalid target',
  };

  /**
   * Parse error response
   *
   * Format: Enn
   * - nn: Two-digit hex error code
   *
   * @param packet - Error packet
   * @returns Parsed error or error
   *
   * @example
   * const result = ErrorParser.parse('E02');
   * if (result.success) {
   *   console.log(result.data.message); // "Invalid memory address"
   * }
   */
  static parse(packet: string): ParseResult<ErrorResponse> {
    try {
      if (!packet.startsWith('E')) {
        return { success: false, error: 'Not an error packet', raw: packet };
      }

      if (packet.length < 2) {
        return { success: false, error: 'Error packet too short', raw: packet };
      }

      const code = packet.substring(1);

      if (!/^[0-9a-fA-F]+$/.test(code)) {
        return { success: false, error: 'Invalid hex in error code', raw: packet };
      }

      const codeNum = parseInt(code, 16);
      const message = this.ERROR_MESSAGES[codeNum] || `Unknown error (code ${code})`;

      return {
        success: true,
        data: {
          code,
          codeNum,
          message
        }
      };
    } catch (error) {
      return {
        success: false,
        error: `Error parse error: ${(error as Error).message}`,
        raw: packet
      };
    }
  }
}

// ============================================================================
// MAIN PARSER UTILITY
// ============================================================================

/**
 * Main RSP parser utility
 *
 * Provides high-level parsing methods and response type detection.
 */
export class RspParser {
  /**
   * Auto-detect response type and parse accordingly
   *
   * @param response - Raw response string (packet data without $ and #checksum)
   * @returns Parsed response with type information
   */
  static parse(response: string): {
    type: 'ok' | 'error' | 'data' | 'stop' | 'monitor' | 'empty';
    data?: any;
    error?: string;
  } {
    // Empty response
    if (response === '') {
      return { type: 'empty' };
    }

    // OK response
    if (response === 'OK') {
      return { type: 'ok' };
    }

    // Error response
    if (response.startsWith('E')) {
      const result = ErrorParser.parse(response);
      if (result.success) {
        return { type: 'error', data: result.data };
      } else {
        return { type: 'error', error: result.error };
      }
    }

    // Stop reply
    if (response.startsWith('S') || response.startsWith('T')) {
      const result = StopReplyParser.parse(response);
      if (result.success) {
        return { type: 'stop', data: result.data };
      } else {
        return { type: 'stop', error: result.error };
      }
    }

    // Monitor output
    if (response.startsWith('O')) {
      const result = MonitorParser.parse(response);
      if (result.success) {
        return { type: 'monitor', data: result.data };
      } else {
        return { type: 'monitor', error: result.error };
      }
    }

    // Data response (default)
    return { type: 'data', data: response };
  }

  /**
   * Check if response indicates success
   *
   * @param response - Raw response string
   * @returns True if success (OK or valid data)
   */
  static isSuccess(response: string): boolean {
    if (response === 'OK') {
      return true;
    }

    if (response.startsWith('E') || response === '') {
      return false;
    }

    return true;
  }

  /**
   * Check if response indicates error
   *
   * @param response - Raw response string
   * @returns True if error
   */
  static isError(response: string): boolean {
    return response.startsWith('E') || response === '';
  }

  // Re-export sub-parsers for convenience
  static Register = RegisterParser;
  static Memory = MemoryParser;
  static StopReply = StopReplyParser;
  static Breakpoint = BreakpointParser;
  static Monitor = MonitorParser;
  static Error = ErrorParser;
}

/**
 * @file SWO/ITM Protocol Decoder
 * @description Concrete implementation of ARM SWO/ITM protocol decoder
 *
 * Implements the ARM CoreSight SWO protocol with full ITM packet parsing.
 * Supports both UART/NRZ and Manchester encoding (though Manchester requires
 * additional hardware support).
 */

import { BaseDecoder } from './BaseDecoder';
import {
  DecoderOptions,
  DecoderState,
  SwoEncoding,
  PacketType,
  PacketHeader,
  SwoPacket,
  InstrumentationPacket,
  HardwarePacket,
  TimestampPacket,
  SyncPacket,
  OverflowPacket,
  HardwareEventType,
  ExceptionType
} from './types';

/**
 * ITM Protocol Constants
 */
const ITM_SYNC_PATTERN = new Uint8Array([0x00, 0x00, 0x00, 0x00, 0x00, 0x80]);
const ITM_OVERFLOW_PATTERN = 0x70;

/**
 * Concrete SWO Decoder Implementation
 *
 * Processes raw SWO byte stream and emits decoded ITM packets.
 * Handles protocol synchronization, packet parsing, and error recovery.
 */
export class SwoDecoder extends BaseDecoder {
  /** Sync pattern for ITM protocol */
  protected readonly SYNC_PATTERN = ITM_SYNC_PATTERN;

  /** Minimum sync bytes for valid sync */
  protected readonly MIN_SYNC_BYTES = 6;

  /** Current packet header being processed */
  private currentHeader: PacketHeader | null = null;

  /** Expected payload bytes for current packet */
  private expectedPayloadBytes: number = 0;

  /** Sync pattern buffer for detection */
  private syncBuffer: Uint8Array = new Uint8Array(this.MIN_SYNC_BYTES);
  private syncBufferPos: number = 0;

  /** Manchester decoder state (if enabled) */
  private manchesterState: number = 0;
  private manchesterBitCount: number = 0;

  constructor(options: DecoderOptions) {
    super(options);

    // Start in sync search mode
    this.state = DecoderState.SYNC_SEARCH;
  }

  /**
   * Handle sync pattern detection
   */
  protected handleSyncSearch(byte: number): void {
    // Shift sync buffer
    if (this.syncBufferPos >= this.MIN_SYNC_BYTES) {
      // Shift left by one
      for (let i = 0; i < this.MIN_SYNC_BYTES - 1; i++) {
        this.syncBuffer[i] = this.syncBuffer[i + 1];
      }
      this.syncBuffer[this.MIN_SYNC_BYTES - 1] = byte;
    } else {
      this.syncBuffer[this.syncBufferPos++] = byte;
    }

    // Check for sync pattern
    if (this.syncBufferPos >= this.MIN_SYNC_BYTES && this.isSyncPattern()) {
      // Emit sync packet
      this.emitPacket({
        type: PacketType.SYNC,
        timestamp: Date.now(),
        raw: new Uint8Array(this.syncBuffer),
        syncCount: this.MIN_SYNC_BYTES
      } as SyncPacket);

      // Reset sync buffer and move to header state
      this.syncBufferPos = 0;
      this.state = DecoderState.HEADER;
      this.resetBuffer();
    }
    // Also check for any valid header byte to auto-sync
    else if (this.options.autoSync && this.isValidHeaderByte(byte)) {
      // Assume we're synchronized and process as header
      this.state = DecoderState.HEADER;
      this.resetBuffer();
      this.handleHeader(byte);
    }
  }

  /**
   * Check if sync buffer contains valid sync pattern
   */
  private isSyncPattern(): boolean {
    // Check for ITM sync: 5+ zeros followed by 0x80
    let zeroCount = 0;
    for (let i = 0; i < this.syncBufferPos - 1; i++) {
      if (this.syncBuffer[i] === 0x00) {
        zeroCount++;
      } else {
        break;
      }
    }

    return zeroCount >= 5 && this.syncBuffer[this.syncBufferPos - 1] === 0x80;
  }

  /**
   * Check if byte could be a valid ITM header
   */
  private isValidHeaderByte(byte: number): boolean {
    // Check for overflow packet
    if (byte === ITM_OVERFLOW_PATTERN) {
      return true;
    }

    // Check for instrumentation packet (0bSSSSSS01 where S = stimulus port)
    if ((byte & 0x03) === 0x01) {
      return true;
    }

    // Check for hardware source packet (0bAAAAA1x0)
    if ((byte & 0x04) === 0x00 && (byte & 0x01) === 0x00) {
      return true;
    }

    // Check for timestamp packets
    if ((byte & 0x0F) === 0x00 && byte !== 0x00) {
      return true;
    }

    // Check for extension packets
    if ((byte & 0x0B) === 0x08) {
      return true;
    }

    return false;
  }

  /**
   * Handle packet header parsing
   */
  protected handleHeader(byte: number): void {
    // Store header byte
    this.addToBuffer(byte);

    // Parse header
    const header = this.parseHeader(byte);
    if (!header) {
      // Invalid header, return to sync search
      this.emitError({
        type: 'parse',
        message: `Invalid header byte: 0x${byte.toString(16)}`,
        context: { byte },
        timestamp: Date.now()
      });
      this.state = DecoderState.SYNC_SEARCH;
      this.resetBuffer();
      return;
    }

    this.currentHeader = header;

    // Handle different packet types
    if (header.type === PacketType.SYNC || header.type === PacketType.OVERFLOW) {
      // These packets have no payload
      this.emitPacketFromHeader(header);
      this.state = DecoderState.HEADER;
      this.resetBuffer();
    } else if (header.type === PacketType.TIMESTAMP) {
      // Timestamp can have continuation bytes
      this.state = DecoderState.PAYLOAD;
      this.expectedPayloadBytes = 0; // Variable length
    } else {
      // Move to payload state
      this.expectedPayloadBytes = header.size;
      this.state = DecoderState.PAYLOAD;
    }
  }

  /**
   * Parse ITM packet header byte
   */
  private parseHeader(byte: number): PacketHeader | null {
    // Check for overflow packet (0x70)
    if (byte === ITM_OVERFLOW_PATTERN) {
      return {
        type: PacketType.OVERFLOW,
        size: 1,
        raw: byte
      };
    }

    // Check for sync packet (part of sync pattern)
    if (byte === 0x00 || byte === 0x80) {
      return {
        type: PacketType.SYNC,
        size: 1,
        raw: byte
      };
    }

    // Check for instrumentation packet (0bSSSSSS01)
    if ((byte & 0x03) === 0x01) {
      const port = (byte >> 3) & 0x1F;
      const size = this.getPayloadSize((byte >> 1) & 0x01);
      return {
        type: PacketType.INSTRUMENTATION,
        size,
        port,
        raw: byte
      };
    }

    // Check for hardware source packet (0bAAAAA1S0)
    if ((byte & 0x04) === 0x04 && (byte & 0x01) === 0x00) {
      const sourceId = (byte >> 3) & 0x1F;
      const size = this.getPayloadSize((byte >> 1) & 0x01);
      return {
        type: PacketType.HARDWARE,
        size,
        sourceId,
        raw: byte
      };
    }

    // Check for timestamp packet (0bCDDD0TS0)
    if ((byte & 0x01) === 0x00 && (byte & 0x0E) !== 0x00) {
      return {
        type: PacketType.TIMESTAMP,
        size: 1, // Initial byte, may have continuations
        raw: byte
      };
    }

    // Check for extension packet (0bCDDD1000)
    if ((byte & 0x0F) === 0x08) {
      return {
        type: PacketType.EXTENSION,
        size: 1,
        raw: byte
      };
    }

    return null;
  }

  /**
   * Get payload size from header size field
   */
  private getPayloadSize(sizeField: number): 1 | 2 | 4 {
    // Size field in header: 00=1, 01=2, 10=4 bytes
    switch (sizeField) {
      case 0x00: return 1;
      case 0x01: return 2;
      case 0x02: return 4;
      default: return 1;
    }
  }

  /**
   * Handle packet payload collection
   */
  protected handlePayload(byte: number): void {
    // Add to buffer
    if (!this.addToBuffer(byte)) {
      // Buffer overflow, reset
      this.state = DecoderState.SYNC_SEARCH;
      return;
    }

    // Handle timestamp continuation
    if (this.currentHeader?.type === PacketType.TIMESTAMP) {
      // Check if this is a continuation byte (bit 7 set)
      if ((byte & 0x80) !== 0) {
        // More bytes to come
        return;
      } else {
        // Last timestamp byte received
        this.emitPacketFromBuffer();
        this.state = DecoderState.HEADER;
        this.resetBuffer();
        this.currentHeader = null;
        return;
      }
    }

    // Check if we have all expected payload bytes
    if (this.bufferPos >= this.expectedPayloadBytes + 1) { // +1 for header
      // Emit complete packet
      this.emitPacketFromBuffer();

      // Reset for next packet
      this.state = DecoderState.HEADER;
      this.resetBuffer();
      this.currentHeader = null;
      this.expectedPayloadBytes = 0;
    }
  }

  /**
   * Emit packet from current header (no payload)
   */
  private emitPacketFromHeader(header: PacketHeader): void {
    const timestamp = Date.now();

    switch (header.type) {
      case PacketType.OVERFLOW:
        this.emitPacket({
          type: PacketType.OVERFLOW,
          timestamp,
          raw: new Uint8Array([header.raw]),
          lostCount: undefined // Can't determine exact count
        } as OverflowPacket);
        break;

      case PacketType.SYNC:
        // Already handled in sync search
        break;
    }
  }

  /**
   * Emit packet from current buffer contents
   */
  private emitPacketFromBuffer(): void {
    if (!this.currentHeader || this.bufferPos === 0) return;

    const timestamp = Date.now();
    const raw = new Uint8Array(this.getBufferContents());

    switch (this.currentHeader.type) {
      case PacketType.INSTRUMENTATION:
        this.emitInstrumentationPacket(raw, timestamp);
        break;

      case PacketType.HARDWARE:
        this.emitHardwarePacket(raw, timestamp);
        break;

      case PacketType.TIMESTAMP:
        this.emitTimestampPacket(raw, timestamp);
        break;

      default:
        // Unknown packet type, emit as base packet
        this.emitPacket({
          type: PacketType.UNKNOWN,
          timestamp,
          raw
        });
    }
  }

  /**
   * Emit instrumentation packet
   */
  private emitInstrumentationPacket(raw: Uint8Array, timestamp: number): void {
    if (!this.currentHeader || this.currentHeader.port === undefined) return;

    const data = raw.slice(1); // Skip header byte
    let text: string | undefined;

    // Try to decode as ASCII text (common for printf)
    try {
      text = new TextDecoder('utf-8', { fatal: false }).decode(data);
      // Only keep if it's printable ASCII
      if (!/^[\x20-\x7E\r\n\t]*$/.test(text)) {
        text = undefined;
      }
    } catch {
      text = undefined;
    }

    this.emitPacket({
      type: PacketType.INSTRUMENTATION,
      timestamp,
      raw,
      port: this.currentHeader.port!,
      data,
      text
    } as InstrumentationPacket);
  }

  /**
   * Emit hardware source packet
   */
  private emitHardwarePacket(raw: Uint8Array, timestamp: number): void {
    if (this.currentHeader?.sourceId === undefined) return;

    const sourceId = this.currentHeader.sourceId;
    const payload = raw.slice(1); // Skip header
    let description: string | undefined;

    // Decode common hardware events
    switch (sourceId) {
      case HardwareEventType.PC_SAMPLE:
        description = 'PC Sample';
        break;

      case HardwareEventType.EXCEPTION:
        if (payload.length >= 2) {
          const exceptionNum = (payload[0] | (payload[1] << 8)) & 0x1FF;
          const eventType = (payload[1] >> 4) & 0x03;
          description = `Exception ${this.getExceptionName(exceptionNum)} - ${
            eventType === 1 ? 'Entry' : eventType === 2 ? 'Exit' : 'Return'
          }`;
        }
        break;

      case HardwareEventType.PC_VALUE:
        if (payload.length === 4) {
          const pc = payload[0] | (payload[1] << 8) | (payload[2] << 16) | (payload[3] << 24);
          description = `PC: 0x${pc.toString(16).padStart(8, '0')}`;
        }
        break;

      case HardwareEventType.DATA_TRACE_ADDR:
        description = 'Data Trace Address';
        break;

      case HardwareEventType.DATA_TRACE_DATA:
        description = 'Data Trace Value';
        break;

      default:
        description = `Hardware Event ${sourceId}`;
    }

    this.emitPacket({
      type: PacketType.HARDWARE,
      timestamp,
      raw,
      sourceId,
      payload,
      description
    } as HardwarePacket);
  }

  /**
   * Get exception name from number
   */
  private getExceptionName(num: number): string {
    switch (num) {
      case ExceptionType.RESET: return 'Reset';
      case ExceptionType.NMI: return 'NMI';
      case ExceptionType.HARDFAULT: return 'HardFault';
      case ExceptionType.MEMMANAGE: return 'MemManage';
      case ExceptionType.BUSFAULT: return 'BusFault';
      case ExceptionType.USAGEFAULT: return 'UsageFault';
      case ExceptionType.SVCALL: return 'SVCall';
      case ExceptionType.DEBUGMON: return 'DebugMon';
      case ExceptionType.PENDSV: return 'PendSV';
      case ExceptionType.SYSTICK: return 'SysTick';
      default:
        if (num >= 16) return `IRQ${num - 16}`;
        return `Exception${num}`;
    }
  }

  /**
   * Emit timestamp packet
   */
  private emitTimestampPacket(raw: Uint8Array, timestamp: number): void {
    // Parse timestamp value from variable-length encoding
    let value = 0;
    const isAbsolute = false;
    let isContinuation = false;

    if (raw.length > 0) {
      const header = raw[0];

      // Check TC bit (bit 7) - 1 = correlation packet
      const isCorrelation = (header & 0x80) !== 0;

      // TS bit (bit 2) - 0 = synchronous, 1 = timestamp delayed
      const isDelayed = (header & 0x04) !== 0;

      // Extract initial timestamp bits
      value = (header >> 4) & 0x07;

      // Process continuation bytes
      let shift = 3;
      for (let i = 1; i < raw.length; i++) {
        const byte = raw[i];
        value |= (byte & 0x7F) << shift;
        shift += 7;

        // Check if more bytes follow
        if ((byte & 0x80) === 0) {
          break;
        }
        isContinuation = true;
      }
    }

    this.emitPacket({
      type: PacketType.TIMESTAMP,
      timestamp,
      raw,
      value,
      isAbsolute,
      isContinuation
    } as TimestampPacket);
  }

  /**
   * Manchester decoding support (requires hardware)
   * Currently not implemented - would require bit-level processing
   */
  private decodeManchesterBit(bit: number): number | null {
    // Manchester encoding uses transitions to represent bits
    // This would require hardware support or very high sample rates
    // Placeholder for future implementation
    return null;
  }

  /**
   * Get decoder capabilities
   */
  public getCapabilities(): string[] {
    const caps = [
      'ITM instrumentation packets',
      'Hardware source packets (DWT)',
      'Timestamp packets',
      'Exception trace',
      'PC sampling',
      'Overflow detection',
      'Auto-synchronization'
    ];

    if (this.options.encoding === SwoEncoding.MANCHESTER) {
      caps.push('Manchester encoding (limited support)');
    }

    return caps;
  }
}
